+using System.Security.Cryptography;
+
+namespace Keon.Contracts.Security;
+
+/// <summary>
+/// Controlled seam for security-relevant randomness (API-key secrets, salts, tokens).
+/// KEON003 bans direct <see cref="RandomNumberGenerator"/> use in enforced assemblies;
+/// randomness must flow through this abstraction so minting has exactly one audited point.
+/// </summary>
+public interface ISecureRandom
+{
+    /// <summary>Lowercase hex token of <paramref name="bytesLength"/> cryptographically random bytes.</summary>
+    string Token(int bytesLength);
+}
+
+/// <summary>Default <see cref="ISecureRandom"/> over the platform CSPRNG.</summary>
+public sealed class SecureRandom : ISecureRandom
+{
+    public static readonly SecureRandom Default = new();
+
+    public string Token(int bytesLength)
+        => Convert.ToHexString(RandomNumberGenerator.GetBytes(bytesLength)).ToLowerInvariant();
+}

