+namespace Keon.Control.ControlPlane;
+
+public static class ControlPlaneEndpoints
+{
+    public static IEndpointRouteBuilder MapControlPlaneEndpoints(this IEndpointRouteBuilder app)
+    {
+        var v1 = app.MapGroup("/v1");
+        var internalV1 = app.MapGroup("/v1/internal");
+
+        v1.MapGet("/plans", (HttpContext httpContext, ControlPlaneStore store) =>
+        {
+            var tenant = TenantControlHttp.ResolveTenantContext(httpContext, store);
+            var plans = store.GetPlans()
+                .Select(plan => new
+                {
+                    plan_id = TenantControlHttp.NormalizePlanId(plan.Code),
+                    name = plan.Name,
+                    monthly_price_usd = plan.MonthlyPriceUsd,
+                    retention_days = plan.ReceiptRetentionDays,
+                    limits = TenantControlHttp.BuildLimits(plan)
+                })
+                .ToArray();
+
+            return Results.Json(TenantControlHttp.Success(httpContext, tenant, plans));
+        });
+
+        v1.MapGet("/me", (HttpContext httpContext, ControlPlaneStore store) =>
+        {
+            var tenant = TenantControlHttp.ResolveTenantContext(httpContext, store);
+            var userId =
+                httpContext.User.FindFirst("sub")?.Value
+                ?? httpContext.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value
+                ?? httpContext.Request.Headers["X-User-Id"].FirstOrDefault()
+                ?? "local-dev-user";
+
+            var response = new TenantIdentityResponse(
+                UserId: userId,
+                TenantId: tenant.TenantId,
+                TenantName: tenant.TenantName,
+                PlanId: tenant.PlanId,
+                Roles: tenant.Roles,
+                OperatorModeEnabled: tenant.Roles.Any(role => string.Equals(role, "operator", StringComparison.OrdinalIgnoreCase)));
