+
+            if (tenant is null)
+            {
+                return Results.NotFound(TenantControlHttp.Failure(httpContext, tenantContext, "TENANT_NOT_FOUND", "Tenant could not be resolved."));
+            }
+
+            var plan = store.GetPlans().First(p => string.Equals(TenantControlHttp.NormalizePlanId(p.Code), tenantContext.PlanId, StringComparison.OrdinalIgnoreCase));
+
+            var response = new TenantProfileResponse(
+                TenantId: tenant.Id,
+                Name: tenant.Name,
