+            return Results.Json(TenantControlHttp.Success(httpContext, tenantContext, response));
+        });
+
+        v1.MapGet("/dashboard/summary", (HttpContext httpContext, ControlPlaneStore store, string? window) =>
+        {
+            var tenant = TenantControlHttp.ResolveTenantContext(httpContext, store);
+            var summary = BuildDashboardSummary(store, tenant.TenantId);
+            return Results.Json(TenantControlHttp.Success(httpContext, tenant, summary));
+        });
+
+        v1.MapGet("/dashboard/health", (HttpContext httpContext, ControlPlaneStore store) =>
+        {
+            var tenant = TenantControlHttp.ResolveTenantContext(httpContext, store);
+            var health = BuildDashboardHealth();
+            return Results.Json(TenantControlHttp.Success(httpContext, tenant, health));
+        });
+
+        v1.MapGet("/dashboard/trust-vector", (HttpContext httpContext, ControlPlaneStore store, string? window) =>
