+
+        v1.MapGet("/me/tenants", (ControlPlaneStore store) => Results.Json(store.GetTenants()));
+
+        v1.MapPost("/tenants", (CreateTenantRequest request, ControlPlaneStore store) =>
+        {
+            if (string.IsNullOrWhiteSpace(request.Name))
