+                return Results.BadRequest(new { error = "name is required" });
+            }
+
+            var tenant = store.CreateTenant(request.Name, request.Slug, request.BillingEmail, request.PlanCode);
+            return Results.Json(tenant, statusCode: StatusCodes.Status201Created);
+        });
+
+        v1.MapGet("/tenants/{tenantId}", (string tenantId, ControlPlaneStore store) =>
+        {
+            var tenant = store.GetTenant(tenantId);
+            return tenant is null ? Results.NotFound() : Results.Json(tenant);
+        });
+
+        v1.MapPost("/tenants/{tenantId}/verify-email", (string tenantId, ControlPlaneStore store) =>
+        {
+            var tenant = store.VerifyTenantEmail(tenantId);
+            return tenant is null ? Results.NotFound() : Results.Json(tenant);
+        });
+
+        v1.MapGet("/tenants/{tenantId}/overview", (string tenantId, ControlPlaneStore store) =>
+        {
+            var overview = store.GetTenantOverview(tenantId);
+            return overview is null ? Results.NotFound() : Results.Json(overview);
+        });
+
+        v1.MapPost("/projects", (CreateProjectRequest request, ControlPlaneStore store) =>
+        {
+            if (string.IsNullOrWhiteSpace(request.TenantId) || string.IsNullOrWhiteSpace(request.Name))
+            {
+                return Results.BadRequest(new { error = "tenantId and name are required" });
+            }
+
+            var project = store.CreateProject(request.TenantId, request.Name, request.Slug);
+            return Results.Json(project, statusCode: StatusCodes.Status201Created);
+        });
+
+        v1.MapGet("/projects", (string? tenantId, ControlPlaneStore store) => Results.Json(store.GetProjects(tenantId)));
+
+        v1.MapPost("/environments", (CreateEnvironmentRequest request, ControlPlaneStore store) =>
+        {
+            if (string.IsNullOrWhiteSpace(request.TenantId) || string.IsNullOrWhiteSpace(request.ProjectId) || string.IsNullOrWhiteSpace(request.Name))
+            {
+                return Results.BadRequest(new { error = "tenantId, projectId, and name are required" });
+            }
+
+            var environment = store.CreateEnvironment(request.TenantId, request.ProjectId, request.Name, request.Slug, request.Kind ?? "development");
+            return Results.Json(environment, statusCode: StatusCodes.Status201Created);
+        });
+
+        v1.MapGet("/environments", (string? tenantId, string? projectId, ControlPlaneStore store) =>
+            Results.Json(store.GetEnvironments(tenantId, projectId)));
+
+        v1.MapPost("/api-keys", (CreateApiKeyRequest request, ControlPlaneStore store) =>
+        {
+            var tenant = store.GetTenant(request.TenantId);
+            if (tenant is null)
+            {
+                return Results.NotFound(new { error = "tenant_not_found" });
+            }
+
+            var result = store.CreateApiKey(request.TenantId, request.ProjectId, request.EnvironmentId, request.Name, request.Mode, tenant.EmailVerified);
+            return Results.Json(new
+            {
+                apiKey = result.Secret,
+                preview = result.Record with { SecretHash = "***", SecretSalt = "***" },
+                shownOnce = true
+            }, statusCode: StatusCodes.Status201Created);
+        });
+
+        v1.MapGet("/api-keys", (string? tenantId, ControlPlaneStore store) => Results.Json(store.GetApiKeys(tenantId)));
+
+        v1.MapGet("/usage/summary", (string tenantId, ControlPlaneStore store) =>
+        {
+            return Results.Json(store.GetUsageSummary(tenantId));
+        });
+
+        v1.MapGet("/usage/timeseries", (string tenantId, ControlPlaneStore store) =>
+        {
+            return Results.Json(store.GetUsageSummary(tenantId).Daily);
+        });
+
+        v1.MapGet("/executions/recent", (string tenantId, ControlPlaneStore store) =>
+        {
+            return Results.Json(store.GetRecentExecutions(tenantId));
+        });
+
+        v1.MapPost("/billing/checkout-session", (BillingCheckoutRequest request, ControlPlaneStore store) =>
+        {
+            var tenant = store.GetTenant(request.TenantId);
+            if (tenant is null)
+            {
+                return Results.NotFound(new { error = "tenant_not_found" });
+            }
+
+            var subscription = store.CreateOrUpdateSubscription(request.TenantId, request.PlanCode, request.PlanCode == "builder" ? "active" : "trialing");
+            return Results.Json(new
+            {
+                checkoutUrl = $"https://billing.keon.local/checkout/{subscription.StripeSubscriptionId}",
+                planCode = request.PlanCode,
+                billingState = subscription.Status
+            });
+        });
+
+        v1.MapPost("/billing/customer-portal-session", (BillingCheckoutRequest request, ControlPlaneStore store) =>
+            Results.Json(new { portalUrl = $"https://billing.keon.local/portal/{request.TenantId}" }));
+
+        v1.MapPost("/billing/webhooks/stripe", (BillingWebhookRequest request, ControlPlaneStore store) =>
+        {
+            var stored = store.StoreWebhookEvent(request.EventId, request.EventType, request.Payload);
+            if (!string.IsNullOrWhiteSpace(request.TenantId) && !string.IsNullOrWhiteSpace(request.PlanCode) && !string.IsNullOrWhiteSpace(request.BillingState))
+            {
+                _ = store.CreateOrUpdateSubscription(request.TenantId, request.PlanCode, request.BillingState);
+            }
+
+            return Results.Json(new { stored.EventId, stored.EventType, stored.StoredAtUtc });
+        });
+
+        v1.MapGet("/billing/summary", (string tenantId, ControlPlaneStore store) =>
+        {
+            var summary = store.GetBillingSummary(tenantId);
+            return summary is null ? Results.NotFound() : Results.Json(summary);
+        });
+
+        internalV1.MapPost("/usage-events", (CreateUsageEventRequest request, ControlPlaneStore store) =>
+        {
+            var record = store.RecordUsageEvent(request);
+            return Results.Json(record, statusCode: StatusCodes.Status202Accepted);
+        });
+
+        internalV1.MapGet("/gateway/api-keys/{prefix}", (string prefix, ControlPlaneStore store) =>
+        {
+            var snapshot = store.ResolveApiKey(prefix);
+            return snapshot is null ? Results.NotFound() : Results.Json(snapshot);
+        });
+
+        internalV1.MapGet("/gateway/tenants/{tenantId}/entitlements", (string tenantId, ControlPlaneStore store) =>
+        {
+            var snapshot = store.GetEntitlementSnapshot(tenantId);
+            return snapshot is null ? Results.NotFound() : Results.Json(snapshot);
+        });
+
+        internalV1.MapGet("/gateway/environments/{environmentId}/state", (string environmentId, ControlPlaneStore store) =>
+        {
+            var state = store.GetEnvironmentState(environmentId);
+            return state is null ? Results.NotFound() : Results.Json(state);
+        });
+
+        return app;
+    }
+
+    private static DashboardSummaryResponse BuildDashboardSummary(ControlPlaneStore store, string tenantId)
+    {
+        var usage = store.GetUsageSummary(tenantId);
+        var recent = store.GetRecentExecutions(tenantId);
+        var activeExecutions = Math.Max(1, recent.Count(execution => execution.OccurredAtUtc >= DateTimeOffset.UtcNow.AddMinutes(-5)));
+        var pendingDecisions = recent.Count(execution => string.Equals(execution.Decision, "PENDING", StringComparison.OrdinalIgnoreCase));
+        var receipts24h = recent.Count(execution => execution.OccurredAtUtc >= DateTimeOffset.UtcNow.AddHours(-24));
+        var authorized = usage.AuthorizedExecutions;
+        var denied = usage.DeniedExecutions;
+        var compliancePct = authorized + denied == 0 ? 100d : Math.Round((double)authorized / Math.Max(authorized + denied, 1) * 100d, 1);
+
+        return new DashboardSummaryResponse(
+            ActiveExecutions: activeExecutions,
+            PendingDecisions: pendingDecisions,
+            CompliancePct24h: compliancePct,
+            Receipts24h: Math.Max(receipts24h, recent.Count),
+            ActiveAgents: 7,
+            AvgLatencyMs: 23.4d);
+    }
+
+    private static IReadOnlyList<DashboardHealthItem> BuildDashboardHealth()
+    {
+        var now = DateTimeOffset.UtcNow;
+        return
+        [
+            new("gateway", "Gateway", "operational", now.AddMinutes(-2), null),
+            new("decision-engine", "Decision Engine", "operational", now.AddMinutes(-3), null),
+            new("receipt-store", "Receipt Store", "operational", now.AddMinutes(-8), null),
+            new("spine", "Spine", "operational", now.AddMinutes(-5), "Receipt chain consistent"),
+            new("evidence-exporter", "Evidence Exporter", "degraded", now.AddMinutes(-11), "Backlog elevated but draining"),
+            new("runtime", "Runtime", "operational", now.AddMinutes(-1), null),
+            new("quorum", "Quorum", "operational", now.AddMinutes(-4), "4/5 members online"),
+        ];
+    }
+
+    private static DashboardTrustVectorResponse BuildTrustVector(ControlPlaneStore store, string tenantId)
+    {
+        var usage = store.GetUsageSummary(tenantId);
+        var volume = Math.Max(usage.TotalQuotaConsumed, 1);
+        var policyPct = Math.Clamp(96d - (usage.DeniedExecutions * 2.5d), 82d, 99d);
+        var receiptsPct = Math.Clamp(90d + (usage.AuthorizedExecutions / (double)volume * 10d), 90d, 100d);
+        var quorumPct = 94d;
+        var latencyPct = 92d;
+        var score = Math.Round((policyPct + receiptsPct + quorumPct + latencyPct) / 4d, 1);
+
+        return new DashboardTrustVectorResponse(
+            Score: score,
+            Policy: new DashboardTrustBreakdownResponse(Math.Round(policyPct, 1), [92, 93, 94, 95, 95, 96, 96]),
+            Receipts: new DashboardTrustBreakdownResponse(Math.Round(receiptsPct, 1), [91, 92, 94, 94, 95, 96, 97]),
+            Quorum: new DashboardTrustBreakdownResponse(quorumPct, [94, 94, 95, 95, 94, 94, 94]),
+            Latency: new DashboardTrustBreakdownResponse(latencyPct, [88, 90, 91, 92, 92, 93, 92]),
+            Trend: "stable");
+    }
+
+    private static IReadOnlyList<DashboardActivityItem> BuildActivity(ControlPlaneStore store, string tenantId, int limit)
+    {
+        var recent = store.GetRecentExecutions(tenantId);
+        var items = recent
+            .SelectMany(execution => new[]
+            {
+                new DashboardActivityItem(
+                    EventId: $"receipt-{execution.ReceiptId ?? execution.ExecutionId}",
+                    EventType: "receipt.issued",
+                    SubjectId: execution.ReceiptId ?? execution.ExecutionId,
+                    Timestamp: execution.OccurredAtUtc,
+                    Title: "Receipt generated",
+                    DetailHref: $"/receipts?receiptId={execution.ReceiptId ?? execution.ExecutionId}",
+                    Message: $"{execution.Decision} for execution {execution.ExecutionId}",
+                    Signer: "keon.runtime"),
+                new DashboardActivityItem(
+                    EventId: $"execution-{execution.ExecutionId}",
+                    EventType: "execution.completed",
+                    SubjectId: execution.ExecutionId,
+                    Timestamp: execution.OccurredAtUtc.AddSeconds(-20),
+                    Title: "Execution updated",
+                    DetailHref: $"/runtime/executions/{execution.ExecutionId}",
+                    Message: $"Decision {execution.Decision}",
+                    Signer: null)
+            })
+            .OrderByDescending(item => item.Timestamp)
+            .Take(Math.Max(limit, 1))
+            .ToArray();
+
+        if (items.Length > 0)
+        {
+            return items;
+        }
+
+        return
+        [
+            new DashboardActivityItem("activity-seed-1", "receipt.issued", "rcpt_seed", DateTimeOffset.UtcNow.AddMinutes(-3), "Receipt generated", "/receipts", "Seed activity", "keon.runtime")
+        ];
+    }
+
+    private static DashboardLastIrreversibleResponse BuildLastIrreversible(ControlPlaneStore store, string tenantId)
+    {
+        var latest = store.GetRecentExecutions(tenantId).FirstOrDefault();
+        var receiptId = latest?.ReceiptId ?? "rcpt_seed_3";
+        var timestamp = latest?.OccurredAtUtc ?? DateTimeOffset.UtcNow.AddMinutes(-17);
+
+        return new DashboardLastIrreversibleResponse(
+            ActionType: "POLICY_UPDATE",
+            Signer: "keon.quorum",
+            Timestamp: timestamp,
+            ReceiptId: receiptId,
+            Href: $"/receipts?receiptId={receiptId}");
+    }
+
+    private static DashboardPolicyOverridesResponse BuildPolicyOverrides(string planId)
+    {
+        var unlocked = string.Equals(planId, "growth", StringComparison.OrdinalIgnoreCase)
+            || string.Equals(planId, "enterprise", StringComparison.OrdinalIgnoreCase);
+
+        return unlocked
+            ? new DashboardPolicyOverridesResponse(false, 2, ["LATENCY_FAIL_OPEN", "MANUAL_REVIEW_ESCALATION"], null)
+            : new DashboardPolicyOverridesResponse(true, 0, [], "growth");
+    }
+
+    private static DashboardQuorumHealthResponse BuildQuorumHealth(string planId)
+    {
+        var required = string.Equals(planId, "enterprise", StringComparison.OrdinalIgnoreCase) ? 5 : 3;
+        var online = required - 1;
+        var status = online >= required ? "healthy" : online == required - 1 ? "at_risk" : "down";
+        return new DashboardQuorumHealthResponse(online, required, status);
+    }
+}

