+using System.Collections.Concurrent;
+using System.Security.Cryptography;
+using System.Text;
+using Keon.Contracts.Security;
+
+namespace Keon.Control.ControlPlane;
+
+public sealed class ControlPlaneStore
+{
+    private readonly ISecureRandom _secureRandom;
+    private readonly ConcurrentDictionary<string, TenantRecord> _tenants = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, ProjectRecord> _projects = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, EnvironmentRecord> _environments = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, ApiKeyRecord> _apiKeys = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, SubscriptionRecord> _subscriptions = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, TenantEntitlementsRecord> _entitlements = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, UsageEventRecord> _usageEvents = new(StringComparer.OrdinalIgnoreCase);
+    private readonly ConcurrentDictionary<string, WebhookEventRecord> _webhookEvents = new(StringComparer.OrdinalIgnoreCase);
+    private readonly IReadOnlyDictionary<string, PlanRecord> _plans;
+
+    public ControlPlaneStore()
+        : this(SecureRandom.Default)
+    {
+    }
+
+    public ControlPlaneStore(ISecureRandom secureRandom)
+    {
+        _secureRandom = secureRandom;
+        _plans = SeedPlans();
+        SeedSampleTenant();
+    }
+
+    public IReadOnlyList<PlanRecord> GetPlans()
+        => _plans.Values.OrderBy(p => p.SortOrder).ToArray();
+
+    public IReadOnlyList<TenantRecord> GetTenants()
+        => _tenants.Values.OrderBy(t => t.CreatedAtUtc).ToArray();
+
+    public TenantRecord CreateTenant(string name, string? slug, string? billingEmail, string? planCode)
+    {
+        var plan = ResolvePlan(planCode);
+        var tenant = new TenantRecord(
+            Id: NewId("ten"),
+            Name: name,
+            Slug: slug ?? Slugify(name),
+            Status: "active",
+            CurrentPlanCode: plan.Code,
+            BillingEmail: billingEmail,
+            EmailVerified: false,
+            CreatedAtUtc: DateTimeOffset.UtcNow,
+            UpdatedAtUtc: DateTimeOffset.UtcNow);
+
+        _tenants[tenant.Id] = tenant;
+        var subscription = CreateOrUpdateSubscription(tenant.Id, plan.Code, plan.Code == "builder" ? "active" : "trialing");
+        _subscriptions[tenant.Id] = subscription;
+        _entitlements[tenant.Id] = ProjectEntitlements(tenant.Id, plan, subscription.Status);
+        return tenant;
+    }
+
+    public TenantRecord? GetTenant(string tenantId)
+        => _tenants.TryGetValue(tenantId, out var tenant) ? tenant : null;
+
+    public TenantRecord? VerifyTenantEmail(string tenantId)
+    {
+        if (!_tenants.TryGetValue(tenantId, out var tenant))
+        {
+            return null;
+        }
+
+        tenant = tenant with { EmailVerified = true, UpdatedAtUtc = DateTimeOffset.UtcNow };
+        _tenants[tenant.Id] = tenant;
+        return tenant;
+    }
+
+    public ProjectRecord CreateProject(string tenantId, string name, string? slug = null)
+    {
+        var project = new ProjectRecord(
+            Id: NewId("prj"),
+            TenantId: tenantId,
+            Name: name,
+            Slug: slug ?? Slugify(name),
+            Status: "active",
+            CreatedAtUtc: DateTimeOffset.UtcNow,
+            UpdatedAtUtc: DateTimeOffset.UtcNow);
+
+        _projects[project.Id] = project;
+        return project;
+    }
+
+    public EnvironmentRecord CreateEnvironment(string tenantId, string projectId, string name, string? slug = null, string kind = "development")
+    {
+        var environment = new EnvironmentRecord(
+            Id: NewId("env"),
+            TenantId: tenantId,
+            ProjectId: projectId,
+            Name: name,
+            Slug: slug ?? Slugify(name),
+            Kind: kind,
+            Status: "active",
+            CreatedAtUtc: DateTimeOffset.UtcNow,
+            UpdatedAtUtc: DateTimeOffset.UtcNow);
+
+        _environments[environment.Id] = environment;
+        return environment;
+    }
+
+    public ApiKeyCreateResult CreateApiKey(string tenantId, string projectId, string environmentId, string name, string mode, bool emailVerified)
+    {
+        if (string.Equals(mode, "live", StringComparison.OrdinalIgnoreCase) && !emailVerified)
+        {
+            throw new InvalidOperationException("Verified email is required before live key issuance.");
+        }
+
+        var prefix = RandomToken(10).ToLowerInvariant();
+        var secret = RandomToken(24);
+        var salt = RandomToken(12);
+        var fullSecret = $"keon_{mode}_{prefix}_{secret}";
+
+        var record = new ApiKeyRecord(
+            Id: NewId("key"),
+            TenantId: tenantId,
+            ProjectId: projectId,
+            EnvironmentId: environmentId,
+            Name: name,
+            Prefix: prefix,
+            SecretSalt: salt,
+            SecretHash: ComputeHash(salt, secret),
+            Mode: mode,
+            Status: "active",
+            LastUsedAtUtc: null,
+            LastUsedIp: null,
+            CreatedAtUtc: DateTimeOffset.UtcNow,
+            UpdatedAtUtc: DateTimeOffset.UtcNow);
+
+        _apiKeys[record.Id] = record;
+        return new ApiKeyCreateResult(record, fullSecret);
+    }
