+    public SubscriptionRecord CreateOrUpdateSubscription(string tenantId, string planCode, string status)
+    {
+        var now = DateTimeOffset.UtcNow;
+        var subscription = new SubscriptionRecord(
+            Id: NewId("sub"),
+            TenantId: tenantId,
+            PlanCode: planCode,
+            Status: status,
+            BillingPeriodStartUtc: new DateTimeOffset(now.Year, now.Month, 1, 0, 0, 0, TimeSpan.Zero),
+            BillingPeriodEndUtc: new DateTimeOffset(now.Year, now.Month, 1, 0, 0, 0, TimeSpan.Zero).AddMonths(1).AddTicks(-1),
+            GracePeriodEndsAtUtc: status == "past_due" ? now.AddDays(7) : null,
+            StripeCustomerId: $"cus_{Guid.NewGuid():N}"[..18],
+            StripeSubscriptionId: $"sub_{Guid.NewGuid():N}"[..18],
+            UpdatedAtUtc: now);
+
+        _subscriptions[tenantId] = subscription;
+        var tenant = GetTenant(tenantId);
+        if (tenant is not null)
+        {
+            _tenants[tenantId] = tenant with { CurrentPlanCode = planCode, UpdatedAtUtc = now };
+            _entitlements[tenantId] = ProjectEntitlements(tenantId, ResolvePlan(planCode), status);
