+    public BillingSummaryResponse? GetBillingSummary(string tenantId)
+    {
+        if (!_subscriptions.TryGetValue(tenantId, out var subscription) || !_entitlements.TryGetValue(tenantId, out var entitlements))
+        {
+            return null;
+        }
+
+        var usage = GetUsageSummary(tenantId);
+        var plan = ResolvePlan(subscription.PlanCode);
+        var overageUnits = Math.Max(usage.AuthorizedExecutions - entitlements.MonthlyExecutionLimit, 0);
+        var overageChargeUsd = overageUnits * plan.OveragePriceUsd;
+
+        return new BillingSummaryResponse(
+            PlanCode: plan.Code,
+            PlanName: plan.Name,
+            BillingState: entitlements.BillingState,
+            GracePeriodEndsAtUtc: subscription.GracePeriodEndsAtUtc,
+            MonthlyPriceUsd: plan.MonthlyPriceUsd,
+            IncludedExecutions: entitlements.MonthlyExecutionLimit,
+            AuthorizedExecutions: usage.AuthorizedExecutions,
+            DeniedExecutions: usage.DeniedExecutions,
+            OverageExecutions: overageUnits,
+            EstimatedOverageUsd: Math.Round(overageChargeUsd, 2),
+            BillingPeriodStartUtc: subscription.BillingPeriodStartUtc,
+            BillingPeriodEndUtc: subscription.BillingPeriodEndUtc);
+    }
