+        return new UsageSummaryResponse(
+            TenantId: tenantId,
+            BillingPeriodStartUtc: monthStart,
+            AuthorizedExecutions: periodEvents.Count(e => string.Equals(e.Decision, "AUTHORIZED", StringComparison.OrdinalIgnoreCase)),
+            DeniedExecutions: periodEvents.Count(e => string.Equals(e.Decision, "DENIED", StringComparison.OrdinalIgnoreCase)),
+            FailedSystemExecutions: periodEvents.Count(e => string.Equals(e.Decision, "FAILED_SYSTEM", StringComparison.OrdinalIgnoreCase)),
+            TotalQuotaConsumed: periodEvents.Length,
