+using System.Security.Claims;
+
+namespace Keon.Control.Security;
+
+/// <summary>
+/// Zero-trust admin guard. Must run BEFORE the rate limiter.
+/// Any request reaching /mcp/admin/*, /mcp/oracle/*, or /mcp/spine/*
+/// without an authenticated identity with a non-empty 'sub' claim
+/// is immediately rejected 401. No IP fallback, no queue.
+/// </summary>
+public sealed class AdminAuthMiddleware(RequestDelegate next)
+{
+    private static readonly string[] AdminPrefixes =
+    [
+        "/mcp/admin",
+        "/mcp/oracle",
+        "/mcp/spine",
+    ];
+
+    public async Task InvokeAsync(HttpContext context)
+    {
+        var path = context.Request.Path.Value ?? string.Empty;
+        var isAdminRoute = AdminPrefixes.Any(p =>
+            path.StartsWith(p, StringComparison.OrdinalIgnoreCase));
+
+        if (isAdminRoute)
+        {
+            var user = context.User;
+
+            var isAuthenticated = user.Identity?.IsAuthenticated == true;
+            var sub = user.FindFirstValue(ClaimTypes.NameIdentifier)
+                   ?? user.FindFirstValue("sub");
+
+            if (!isAuthenticated || string.IsNullOrWhiteSpace(sub))
+            {
+                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
+                context.Response.ContentType = "application/json";
+                await context.Response.WriteAsync(
+                    """{"error":"unauthorized","message":"A valid authenticated identity with a subject claim is required for admin routes."}""");
+                return;
+            }
+        }
+
+        await next(context);
+    }
+}

