+namespace Keon.Control.Security;
+
+/// <summary>
+/// Application-layer defense against ACA origin bypass.
+/// Validates the X-Azure-FDID header matches the configured Front Door ID.
+/// Combined with ACA ingress restricted to AzureFrontDoor.Backend service tag,
+/// this makes origin bypass mathematically impossible.
+///
+/// Disabled when FrontDoor:Enabled = false (local dev / non-Azure environments).
+/// </summary>
+public sealed class FrontDoorValidationMiddleware(RequestDelegate next, IConfiguration configuration, ILogger<FrontDoorValidationMiddleware> logger)
+{
+    private const string FdIdHeader = "X-Azure-FDID";
+
+    public async Task InvokeAsync(HttpContext context)
+    {
+        var enabled = configuration.GetValue("FrontDoor:Enabled", false);
+        if (!enabled)
+        {
+            await next(context);
+            return;
+        }
+
+        var expectedFdId = configuration["FrontDoor:ProfileId"];
+        if (string.IsNullOrWhiteSpace(expectedFdId))
+        {
+            // Misconfiguration: Front Door enabled but no ID set → fail closed.
+            logger.LogError("FrontDoor:Enabled is true but FrontDoor:ProfileId is not configured. Rejecting request.");
+            context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;
+            await context.Response.WriteAsync("""{"error":"service_misconfigured"}""");
+            return;
+        }
+
+        if (!context.Request.Headers.TryGetValue(FdIdHeader, out var incomingFdId) ||
+            !string.Equals(incomingFdId.ToString(), expectedFdId, StringComparison.OrdinalIgnoreCase))
+        {
+            logger.LogWarning("Request rejected: missing or invalid {Header}. Path={Path}",
+                FdIdHeader, context.Request.Path);
+            context.Response.StatusCode = StatusCodes.Status403Forbidden;
+            context.Response.ContentType = "application/json";
+            await context.Response.WriteAsync(
+                """{"error":"forbidden","message":"Direct origin access is not permitted."}""");
+            return;
+        }
+
+        await next(context);
+    }
+}

