+using System.Security.Cryptography;
+using System.Text;
+using System.Text.Json;
+
+namespace Keon.Control.Security;
+
+/// <summary>
+/// Idempotency enforcement middleware for mutating MCP operations.
+/// Reads the Idempotency-Key header, checks Table Storage atomically,
+/// and short-circuits with 409 on replay. Fails closed (503) if the store
+/// is unavailable.
+///
+/// Only applies to POST/PUT/PATCH requests that include an Idempotency-Key header.
+/// </summary>
+public sealed class IdempotencyMiddleware(
+    RequestDelegate next,
+    IdempotencyTableService idempotency,
+    ILogger<IdempotencyMiddleware> logger)
+{
+    private const string IdempotencyKeyHeader = "Idempotency-Key";
+
+    private static readonly HashSet<string> MutatingMethods = new(StringComparer.OrdinalIgnoreCase)
+    {
+        HttpMethods.Post, HttpMethods.Put, HttpMethods.Patch,
+    };
+
+    public async Task InvokeAsync(HttpContext context)
+    {
+        if (!MutatingMethods.Contains(context.Request.Method))
+        {
+            await next(context);
+            return;
+        }
+
+        if (!context.Request.Headers.TryGetValue(IdempotencyKeyHeader, out var keyValues) ||
+            string.IsNullOrWhiteSpace(keyValues.ToString()))
+        {
+            await next(context);
+            return;
+        }
+
+        var idempotencyKey = keyValues.ToString().Trim();
+        if (idempotencyKey.Length > 256)
+        {
+            context.Response.StatusCode = StatusCodes.Status400BadRequest;
+            context.Response.ContentType = "application/json";
+            await context.Response.WriteAsync("""{"error":"idempotency_key_too_long"}""");
+            return;
+        }
+
+        // Derive a stable outcome hash from the request for replay verification.
+        // We use the key + request path as a lightweight fingerprint placeholder.
+        // The outcome hash will be updated after a successful response.
+        var fingerprint = $"{idempotencyKey}:{context.Request.Path}";
+        var outcomeHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(fingerprint)));
+
+        var tenantId = context.User.FindFirst("tenant_id")?.Value
+                    ?? context.User.FindFirst("tid")?.Value;
+
+        try
+        {
+            var existingHash = await idempotency.RecordAsync(idempotencyKey, outcomeHash, tenantId, context.RequestAborted);
+
+            if (existingHash is not null)
+            {
+                logger.LogInformation("Idempotency replay detected. Key={Key} Path={Path}", idempotencyKey, context.Request.Path);
+                context.Response.StatusCode = StatusCodes.Status409Conflict;
+                context.Response.ContentType = "application/json";
+                await context.Response.WriteAsync(JsonSerializer.Serialize(new
+                {
+                    error = "idempotency_replay",
+                    message = "This request has already been processed.",
+                    idempotency_key = idempotencyKey,
+                }));
+                return;
+            }
+        }
+        catch (Exception ex)
+        {
+            // Fail closed — idempotency store unavailable → 503, never let replay through.
+            logger.LogError(ex, "Idempotency store unavailable. Failing closed. Key={Key}", idempotencyKey);
+            context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;
+            context.Response.ContentType = "application/json";
+            context.Response.Headers.RetryAfter = "5";
+            await context.Response.WriteAsync(
+                """{"error":"idempotency_store_unavailable","message":"Service temporarily unavailable. Retry after 5 seconds."}""");
+            return;
+        }
+
+        await next(context);
+    }
+}

