+using Azure;
+using Azure.Data.Tables;
+
+namespace Keon.Control.Security;
+
+/// <summary>
+/// Distributed idempotency store backed by Azure Table Storage.
+/// Uses the native uniqueness constraint of Table Storage (PartitionKey + RowKey)
+/// to guarantee atomicity without a check-then-insert race (TOCTOU).
+///
+/// Contract:
+///   RecordAsync → null   = first time, caller should execute
+///   RecordAsync → string = existing outcome hash, caller should return 409
+///   If Table Storage is unavailable → throws, caller maps to 503 (fail-closed).
+/// </summary>
+public sealed class IdempotencyTableService
+{
+    private const string TableName = "KeonIdempotency";
+    private const string DefaultPartition = "global";
+    private readonly TableClient _table;
+
+    public IdempotencyTableService(IConfiguration configuration)
+    {
+        var connectionString = configuration["IdempotencyStore:TableStorage:ConnectionString"]
+            ?? throw new InvalidOperationException(
+                "IdempotencyStore:TableStorage:ConnectionString is required.");
+
+        var serviceClient = new TableServiceClient(connectionString);
+        serviceClient.CreateTableIfNotExists(TableName);
+        _table = serviceClient.GetTableClient(TableName);
+    }
+
+    /// <summary>
+    /// Attempts to claim the idempotency key by inserting an entity atomically.
+    /// Returns null on success (first request), or the stored outcome hash on replay.
+    /// </summary>
+    public async Task<string?> RecordAsync(
+        string idempotencyKey,
+        string outcomeHash,
+        string? tenantId = null,
+        CancellationToken ct = default)
+    {
+        var partitionKey = string.IsNullOrWhiteSpace(tenantId) ? DefaultPartition : tenantId;
+        var entity = new IdempotencyEntity
+        {
+            PartitionKey = partitionKey,
+            RowKey = idempotencyKey,
+            OutcomeHash = outcomeHash,
+            ExpiresAtUtc = DateTimeOffset.UtcNow.AddHours(24),
+        };
+
+        try
+        {
+            // Atomic insert — throws 409 if RowKey already exists. No check-then-insert.
+            await _table.AddEntityAsync(entity, ct);
+            return null; // First request: proceed
+        }
+        catch (RequestFailedException ex) when (ex.Status == 409)
+        {
+            // Replay detected: retrieve and return the stored outcome hash.
+            var existing = await _table.GetEntityAsync<IdempotencyEntity>(partitionKey, idempotencyKey, cancellationToken: ct);
+            return existing.Value.OutcomeHash;
+        }
+        // Any other exception (network, auth) propagates → caller maps to 503 fail-closed.
+    }
+}
+
+public sealed class IdempotencyEntity : ITableEntity
+{
+    public string PartitionKey { get; set; } = default!;
+    public string RowKey { get; set; } = default!;
+    public DateTimeOffset? Timestamp { get; set; }
+    public ETag ETag { get; set; }
+    public string OutcomeHash { get; set; } = default!;
+    public DateTimeOffset ExpiresAtUtc { get; set; }
+}

