+using System.Security.Claims;
+using System.Threading.RateLimiting;
+using Microsoft.AspNetCore.RateLimiting;
+
+namespace Keon.Control.Security;
+
+/// <summary>
+/// Token-bucket rate limiter policies.
+/// mcp_public    – /mcp/tools/list, /mcp/tools/call: 5 tok/s refill, burst 50
+/// mcp_admin_partitioned – /mcp/admin/*, /mcp/oracle/*, /mcp/spine/*: 2 tok/s, burst 20, per-sub
+/// </summary>
+public static class RateLimiterPolicies
+{
+    public const string McpPublic = "mcp_public";
+    public const string McpAdminPartitioned = "mcp_admin_partitioned";
+
+    public static IServiceCollection AddKeonRateLimiting(this IServiceCollection services)
+    {
+        services.AddRateLimiter(options =>
+        {
+            options.OnRejected = async (ctx, ct) =>
+            {
+                ctx.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
+
+                if (ctx.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfter))
+                {
+                    ctx.HttpContext.Response.Headers.RetryAfter =
+                        ((long)retryAfter.TotalSeconds).ToString();
+                }
+
+                ctx.HttpContext.Response.ContentType = "application/json";
+                await ctx.HttpContext.Response.WriteAsync(
+                    """{"error":"rate_limit_exceeded","message":"Too many requests. Retry after the indicated seconds."}""",
+                    ct);
+            };
+
+            // Public MCP endpoints – token bucket, 5 tok/s refill, burst 50, keyed by IP
+            options.AddTokenBucketLimiter(McpPublic, o =>
+            {
+                o.TokenLimit = 50;
+                o.ReplenishmentPeriod = TimeSpan.FromSeconds(1);
+                o.TokensPerPeriod = 5;
+                o.AutoReplenishment = true;
+                o.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
+                o.QueueLimit = 0; // no queue – immediate 429
+            });
+
+            // Admin endpoints – token bucket, 2 tok/s refill, burst 20, keyed by subject claim
+            options.AddPolicy(McpAdminPartitioned, ctx =>
+            {
+                var sub = ctx.User.FindFirstValue(ClaimTypes.NameIdentifier)
+                       ?? ctx.User.FindFirstValue("sub");
+
+                // Sub must already be validated by AdminAuthMiddleware before reaching here.
+                // Use a deliberate narrow bucket if sub is somehow empty (fallback-safe).
+                var partitionKey = string.IsNullOrWhiteSpace(sub) ? "__no_sub__" : sub;
+
+                return RateLimitPartition.GetTokenBucketLimiter(partitionKey, _ => new TokenBucketRateLimiterOptions
+                {
+                    TokenLimit = 20,
+                    ReplenishmentPeriod = TimeSpan.FromSeconds(1),
+                    TokensPerPeriod = 2,
+                    AutoReplenishment = true,
+                    QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
+                    QueueLimit = 0,
+                });
+            });
+        });
+
+        return services;
+    }
+}

