+using System.Text.Json;
+using Keon.Canonicalization;
+using Keon.Runtime.Receipts;
+using Microsoft.Extensions.DependencyInjection.Extensions;
+
+namespace Keon.Runtime.Api;
+
+internal static class ProducerHttpComposition
+{
+    internal const string ReceiptDatabaseKey = "KEON_RUNTIME_PRODUCER_RECEIPT_DB";
+    internal const string SigningKeyIdKey = "KEON_RUNTIME_PRODUCER_SIGNING_KEY_ID";
+    internal const string SigningPrivateKeyKey = "KEON_RUNTIME_PRODUCER_SIGNING_PRIVATE_KEY_BASE64";
+    internal const string CredentialsKey = "KEON_RUNTIME_PRODUCER_CREDENTIALS";
+
+    private static readonly JsonSerializerOptions ConfigJsonOptions = new()
+    {
+        PropertyNameCaseInsensitive = true
+    };
+
+    internal static void AddProducerHttpContract(this IServiceCollection services, IConfiguration configuration)
+    {
+        services.TryAddSingleton(sp => CreateComposition(sp.GetRequiredService<IConfiguration>()));
+        services.TryAddSingleton<IProducerServiceIdentityMapper>(sp =>
+            sp.GetRequiredService<ProducerHttpCompositionResult>().IdentityMapper);
+        services.TryAddSingleton<IProducerReceiptBackend>(sp =>
+            sp.GetRequiredService<ProducerHttpCompositionResult>().Backend);
+    }
+
+    private static ProducerHttpCompositionResult CreateComposition(IConfiguration configuration)
+    {
+        var credentials = ReadCredentials(configuration[CredentialsKey], out var credentialsConfigured);
+        var identityMapper = new ConfiguredProducerServiceIdentityMapper(credentials, credentialsConfigured);
+
+        if (!TryCreateStore(configuration, out var store))
+        {
+            return new(identityMapper, new UnavailableProducerReceiptBackend());
+        }
+
+        return new(identityMapper, new SqliteProducerReceiptBackend(store!));
+    }
+
+    private static IReadOnlyList<ProducerServiceCredential> ReadCredentials(
+        string? raw,
+        out bool configured)
+    {
+        configured = false;
+        if (string.IsNullOrWhiteSpace(raw))
+        {
+            return Array.Empty<ProducerServiceCredential>();
+        }
+
+        try
+        {
+            var specs = JsonSerializer.Deserialize<ProducerServiceCredentialSpec[]>(raw, ConfigJsonOptions);
+            if (specs is null || specs.Length == 0)
+            {
+                return Array.Empty<ProducerServiceCredential>();
+            }
+
+            var credentials = new List<ProducerServiceCredential>(specs.Length);
+            var credentialIds = new HashSet<string>(StringComparer.Ordinal);
+            var credentialSecrets = new HashSet<string>(StringComparer.Ordinal);
+            foreach (var spec in specs)
+            {
+                if (string.IsNullOrWhiteSpace(spec.CredentialId) ||
+                    string.IsNullOrWhiteSpace(spec.Secret) ||
+                    string.IsNullOrWhiteSpace(spec.TenantId) ||
+                    string.IsNullOrWhiteSpace(spec.ActorId) ||
+                    string.IsNullOrWhiteSpace(spec.Subject) ||
+                    string.IsNullOrWhiteSpace(spec.Audience) ||
+                    string.IsNullOrWhiteSpace(spec.CredentialType))
+                {
+                    return Array.Empty<ProducerServiceCredential>();
+                }
+
+                if (!credentialIds.Add(spec.CredentialId) || !credentialSecrets.Add(spec.Secret))
+                {
+                    return Array.Empty<ProducerServiceCredential>();
+                }
+
+                credentials.Add(new ProducerServiceCredential(
+                    spec.CredentialId,
+                    spec.Secret,
+                    new ProducerAuthBinding(
+                        spec.TenantId,
+                        spec.ActorId,
+                        spec.Subject,
+                        spec.Audience,
+                        spec.CredentialType,
+                        spec.CredentialId)));
+            }
+
+            configured = true;
+            return credentials;
+        }
+        catch (JsonException)
+        {
+            return Array.Empty<ProducerServiceCredential>();
+        }
+    }
+
+    private static bool TryCreateStore(
+        IConfiguration configuration,
+        out SqliteProducerReceiptStore? store)
+    {
+        store = null;
+        var connectionString = configuration[ReceiptDatabaseKey];
+        var keyId = configuration[SigningKeyIdKey];
+        var encodedPrivateKey = configuration[SigningPrivateKeyKey];
+        if (string.IsNullOrWhiteSpace(connectionString) ||
+            string.IsNullOrWhiteSpace(keyId) ||
+            string.IsNullOrWhiteSpace(encodedPrivateKey))
+        {
+            return false;
+        }
+
+        try
+        {
+            var privateKey = Convert.FromBase64String(encodedPrivateKey);
+            if (privateKey.Length != 32)
+            {
+                return false;
+            }
+
+            var signer = new Ed25519ProducerReceiptSigner(keyId, privateKey);
+            var keys = new InMemoryProducerReceiptVerificationKeyProvider(
+                new Dictionary<string, byte[]>(StringComparer.Ordinal)
+                {
+                    [signer.KeyId] = Ed25519Signature.DerivePublicKey(privateKey)
+                });
+            store = new SqliteProducerReceiptStore(connectionString, signer, keys);
+            return true;
+        }
+        catch (Exception ex) when (ex is ArgumentException or FormatException or InvalidOperationException or System.Data.SQLite.SQLiteException)
+        {
+            return false;
+        }
+    }
+
+    internal sealed record ProducerHttpCompositionResult(
+        IProducerServiceIdentityMapper IdentityMapper,
