+using System.Security.Cryptography;
+using System.Text.Json;
+using System.Text.Json.Serialization;
+using Keon.Runtime.Receipts;
+
+namespace Keon.Runtime.Api;
+
+internal static class ProducerHttpContract
+{
+    public const string BasePath = "/runtime/v2/producer";
+    public const string AuthorizationPath = BasePath + "/authorization";
+    public const string CompletionPath = BasePath + "/completion";
+    public const string ReceiptPath = BasePath + "/receipts/{receiptId}";
+    public const string BearerScheme = "Bearer";
+    public const string AuthNotConfigured = "PRODUCER_AUTH_NOT_CONFIGURED";
+    public const string AuthenticationRequired = "PRODUCER_AUTHENTICATION_REQUIRED";
+    public const string AuthenticationInvalid = "PRODUCER_AUTHENTICATION_INVALID";
+    public const string StoreUnavailable = "PRODUCER_RECEIPT_STORE_UNAVAILABLE";
+}
+
+public sealed record ProducerAuthorizationHttpRequest(
+    [property: JsonPropertyName("operationId")] string? OperationId,
+    [property: JsonPropertyName("idempotencyKey")] string? IdempotencyKey,
+    [property: JsonPropertyName("requestFingerprint")] string? RequestFingerprint,
+    [property: JsonPropertyName("status")] string? Status);
+
+public sealed record ProducerCompletionHttpRequest(
+    [property: JsonPropertyName("operationId")] string? OperationId,
+    [property: JsonPropertyName("idempotencyKey")] string? IdempotencyKey,
+    [property: JsonPropertyName("requestFingerprint")] string? RequestFingerprint,
+    [property: JsonPropertyName("authorizationReceiptId")] string? AuthorizationReceiptId,
+    [property: JsonPropertyName("status")] string? Status,
+    [property: JsonPropertyName("resultFingerprint")] string? ResultFingerprint,
+    [property: JsonPropertyName("completedAtUtc")] DateTimeOffset? CompletedAtUtc);
+
+public sealed record ProducerHttpEnvelope<T>(
+    [property: JsonPropertyName("success")] bool Success,
+    [property: JsonPropertyName("data")] T? Data,
+    [property: JsonPropertyName("error")] ProducerHttpError? Error);
+
+public sealed record ProducerHttpError(
+    [property: JsonPropertyName("code")] string Code,
+    [property: JsonPropertyName("message")] string Message);
+
+internal sealed record ProducerServiceCredential(
+    string CredentialId,
+    string Secret,
+    ProducerAuthBinding Binding);
+
+internal sealed record ProducerIdentityResolution(
+    ProducerAuthBinding? Binding,
+    int StatusCode,
+    string ErrorCode,
+    string Message)
+{
+    public bool Succeeded => Binding is not null;
+
+    public static ProducerIdentityResolution Success(ProducerAuthBinding binding)
+        => new(binding, StatusCodes.Status200OK, string.Empty, string.Empty);
+}
+
+internal interface IProducerServiceIdentityMapper
+{
+    ProducerIdentityResolution Resolve(HttpContext context);
+}
+
+internal sealed class ConfiguredProducerServiceIdentityMapper(
+    IReadOnlyList<ProducerServiceCredential> credentials,
+    bool configurationPresent) : IProducerServiceIdentityMapper
+{
+    public ProducerIdentityResolution Resolve(HttpContext context)
+    {
+        if (!configurationPresent || credentials.Count == 0)
+        {
+            return new(
+                null,
+                StatusCodes.Status503ServiceUnavailable,
+                ProducerHttpContract.AuthNotConfigured,
+                "Producer service identity authentication is not configured.");
+        }
+
+        if (!context.Request.Headers.TryGetValue("Authorization", out var values) ||
+            values.Count != 1 ||
+            string.IsNullOrWhiteSpace(values[0]))
+        {
+            return new(
+                null,
+                StatusCodes.Status401Unauthorized,
+                ProducerHttpContract.AuthenticationRequired,
+                "A producer service credential is required.");
+        }
+
+        var authorization = values[0]!;
+        var separator = authorization.IndexOf(' ');
+        if (separator <= 0 ||
+            !authorization[..separator].Equals(ProducerHttpContract.BearerScheme, StringComparison.OrdinalIgnoreCase) ||
+            separator == authorization.Length - 1)
+        {
+            return new(
+                null,
+                StatusCodes.Status401Unauthorized,
+                ProducerHttpContract.AuthenticationInvalid,
+                "The producer service credential is invalid.");
+        }
+
+        var suppliedSecret = authorization[(separator + 1)..].Trim();
+        var suppliedDigest = SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(suppliedSecret));
+        foreach (var credential in credentials)
+        {
+            if (CryptographicOperations.FixedTimeEquals(
+                    suppliedDigest,
+                    SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(credential.Secret))))
+            {
+                return ProducerIdentityResolution.Success(credential.Binding);
+            }
+        }
+
+        return new(
+            null,
+            StatusCodes.Status401Unauthorized,
+            ProducerHttpContract.AuthenticationInvalid,
+            "The producer service credential is invalid.");
+    }
+}
+
+internal interface IProducerReceiptBackend
+{
+    ProducerReceipt Issue(ProducerReceiptIssueRequest request);
+
+    ProducerReceiptReadResult Retrieve(ProducerReceiptLookup lookup);
+}
+
+internal sealed class SqliteProducerReceiptBackend(SqliteProducerReceiptStore store) : IProducerReceiptBackend
+{
+    public ProducerReceipt Issue(ProducerReceiptIssueRequest request)
+    {
+        try
+        {
+            return store.Issue(request);
+        }
+        catch (System.Data.SQLite.SQLiteException ex)
+        {
+            throw new ProducerReceiptStoreUnavailableException(ex);
+        }
+        catch (InvalidOperationException ex)
+        {
+            throw new ProducerReceiptStoreUnavailableException(ex);
+        }
+    }
+
+    public ProducerReceiptReadResult Retrieve(ProducerReceiptLookup lookup)
+    {
+        try
+        {
+            return store.Retrieve(lookup);
+        }
+        catch (System.Data.SQLite.SQLiteException ex)
+        {
+            throw new ProducerReceiptStoreUnavailableException(ex);
+        }
+        catch (InvalidOperationException ex)
+        {
+            throw new ProducerReceiptStoreUnavailableException(ex);
+        }
+    }
+}
+
+internal sealed class UnavailableProducerReceiptBackend : IProducerReceiptBackend
+{
+    public ProducerReceipt Issue(ProducerReceiptIssueRequest request)
+        => throw new ProducerReceiptStoreUnavailableException();
+
+    public ProducerReceiptReadResult Retrieve(ProducerReceiptLookup lookup)
+        => throw new ProducerReceiptStoreUnavailableException();
+}
+
+internal sealed class ProducerReceiptStoreUnavailableException : Exception
+{
+    public ProducerReceiptStoreUnavailableException(Exception? innerException = null)
+        : base("The durable producer receipt store is unavailable.", innerException)
+    {
+    }
+}

