+using System.Text.Json;
+using System.Text.Json.Serialization;
+using Keon.Runtime.Receipts;
+
+namespace Keon.Runtime.Api;
+
+internal static class ProducerHttpEndpoints
+{
+    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
+    {
+        Converters = { new JsonStringEnumConverter(JsonNamingPolicy.CamelCase) }
+    };
+
+    internal static IEndpointRouteBuilder MapProducerHttpContract(this IEndpointRouteBuilder endpoints)
+    {
+        var group = endpoints.MapGroup(ProducerHttpContract.BasePath);
+        group.MapPost("/authorization", IssueAuthorizationAsync);
+        group.MapPost("/completion", IssueCompletionAsync);
+        group.MapGet("/receipts/{receiptId}", RetrieveAsync);
+        return endpoints;
+    }
+
+    private static Task<IResult> IssueAuthorizationAsync(
+        ProducerAuthorizationHttpRequest? request,
+        HttpContext context,
+        IProducerServiceIdentityMapper identityMapper,
+        IProducerReceiptBackend backend)
+    {
+        var identity = identityMapper.Resolve(context);
+        if (!identity.Succeeded)
+        {
+            return Task.FromResult<IResult>(Error(identity.StatusCode, identity.ErrorCode, identity.Message));
+        }
+
+        if (request is null ||
+            string.IsNullOrWhiteSpace(request.OperationId) ||
+            string.IsNullOrWhiteSpace(request.IdempotencyKey) ||
+            string.IsNullOrWhiteSpace(request.RequestFingerprint) ||
+            !Enum.TryParse<ProducerReceiptStatus>(request.Status, ignoreCase: true, out var status) ||
+            !string.Equals(request.Status, "authorized", StringComparison.Ordinal) &&
+            !string.Equals(request.Status, "denied", StringComparison.Ordinal) ||
+            status is not ProducerReceiptStatus.Authorized and not ProducerReceiptStatus.Denied)
+        {
+            return Task.FromResult<IResult>(Error(
+                StatusCodes.Status400BadRequest,
+                "AUTHORIZATION_REQUEST_INVALID",
+                "operationId, idempotencyKey, requestFingerprint, and an authorized or denied status are required."));
+        }
+
+        var issue = new ProducerReceiptIssueRequest(
+            ProducerReceiptPhase.Authorization,
+            status,
+            request.OperationId,
+            request.IdempotencyKey,
+            request.RequestFingerprint,
+            identity.Binding!,
+            null,
+            null);
+        return Task.FromResult<IResult>(Issue(issue, backend));
+    }
+
+    private static Task<IResult> IssueCompletionAsync(
+        ProducerCompletionHttpRequest? request,
+        HttpContext context,
+        IProducerServiceIdentityMapper identityMapper,
+        IProducerReceiptBackend backend)
+    {
+        var identity = identityMapper.Resolve(context);
+        if (!identity.Succeeded)
+        {
+            return Task.FromResult<IResult>(Error(identity.StatusCode, identity.ErrorCode, identity.Message));
+        }
+
+        if (request is null ||
+            string.IsNullOrWhiteSpace(request.OperationId) ||
+            string.IsNullOrWhiteSpace(request.IdempotencyKey) ||
+            string.IsNullOrWhiteSpace(request.RequestFingerprint) ||
+            string.IsNullOrWhiteSpace(request.AuthorizationReceiptId) ||
+            string.IsNullOrWhiteSpace(request.ResultFingerprint) ||
+            !Enum.TryParse<ProducerReceiptStatus>(request.Status, ignoreCase: true, out var status) ||
+            !string.Equals(request.Status, "completed", StringComparison.Ordinal) &&
+            !string.Equals(request.Status, "failed", StringComparison.Ordinal) ||
+            status is not ProducerReceiptStatus.Completed and not ProducerReceiptStatus.Failed)
+        {
+            return Task.FromResult<IResult>(Error(
+                StatusCodes.Status400BadRequest,
+                "COMPLETION_REQUEST_INVALID",
+                "operationId, idempotencyKey, requestFingerprint, authorizationReceiptId, resultFingerprint, and a completed or failed status are required."));
+        }
+
+        var issue = new ProducerReceiptIssueRequest(
+            ProducerReceiptPhase.Completion,
+            status,
+            request.OperationId,
+            request.IdempotencyKey,
+            request.RequestFingerprint,
+            identity.Binding!,
+            request.AuthorizationReceiptId,
+            request.ResultFingerprint,
+            request.CompletedAtUtc);
+        return Task.FromResult<IResult>(Issue(issue, backend));
+    }
+
+    private static Task<IResult> RetrieveAsync(
+        string receiptId,
+        HttpContext context,
+        IProducerServiceIdentityMapper identityMapper,
+        IProducerReceiptBackend backend)
+    {
+        var identity = identityMapper.Resolve(context);
+        if (!identity.Succeeded)
+        {
+            return Task.FromResult<IResult>(Error(identity.StatusCode, identity.ErrorCode, identity.Message));
+        }
+
+        if (string.IsNullOrWhiteSpace(receiptId))
+        {
+            return Task.FromResult<IResult>(Error(
+                StatusCodes.Status400BadRequest,
+                "RECEIPT_ID_REQUIRED",
+                "receiptId is required."));
+        }
+
+        try
+        {
+            var result = backend.Retrieve(new ProducerReceiptLookup(
+                receiptId,
+                identity.Binding!.TenantId,
+                identity.Binding.ActorId,
+                identity.Binding.Audience));
+            if (result.Found)
+            {
+                return Task.FromResult<IResult>(Ok(result.Receipt!));
+            }
+
+            return Task.FromResult<IResult>(Error(
+                RetrievalStatus(result.ErrorCode),
+                result.ErrorCode ?? ProducerHttpContract.StoreUnavailable,
+                RetrievalMessage(result.ErrorCode)));
+        }
+        catch (ProducerReceiptStoreUnavailableException)
+        {
+            return Task.FromResult<IResult>(Error(
+                StatusCodes.Status503ServiceUnavailable,
+                ProducerHttpContract.StoreUnavailable,
+                "The durable producer receipt store is unavailable."));
+        }
+    }
+
+    private static IResult Issue(ProducerReceiptIssueRequest request, IProducerReceiptBackend backend)
+    {
+        try
+        {
+            return Ok(backend.Issue(request));
+        }
+        catch (ProducerReceiptConflictException ex)
+        {
+            return Error(StatusCodes.Status409Conflict, ex.Code, ConflictMessage(ex.Code));
+        }
+        catch (ProducerReceiptValidationException ex)
+        {
+            return Error(ValidationStatus(ex.Code), ex.Code, ValidationMessage(ex.Code));
+        }
+        catch (ProducerReceiptStoreUnavailableException)
+        {
+            return Error(
+                StatusCodes.Status503ServiceUnavailable,
+                ProducerHttpContract.StoreUnavailable,
+                "The durable producer receipt store is unavailable.");
+        }
+    }
+
+    private static IResult Ok(ProducerReceipt receipt)
+        => Results.Json(new ProducerHttpEnvelope<ProducerReceipt>(true, receipt, null), JsonOptions);
+
+    private static IResult Error(int statusCode, string code, string message)
+        => Results.Json(
+            new ProducerHttpEnvelope<object>(false, null, new ProducerHttpError(code, message)),
+            JsonOptions,
+            statusCode: statusCode);
+
+    private static int ValidationStatus(string code)
+        => code is "AUTHORIZATION_NOT_FOUND" or "AUTHORIZATION_CONTEXT_MISMATCH"
+            ? StatusCodes.Status409Conflict
+            : code == "SIGNATURE_INVALID"
+                ? StatusCodes.Status403Forbidden
+                : StatusCodes.Status400BadRequest;
+
+    private static int RetrievalStatus(string? code)
+        => code == "RECEIPT_NOT_FOUND"
+            ? StatusCodes.Status404NotFound
+            : code is "TENANT_MISMATCH" or "ACTOR_MISMATCH" or "AUDIENCE_MISMATCH" or "SIGNATURE_INVALID"
+                ? StatusCodes.Status403Forbidden
+                : StatusCodes.Status503ServiceUnavailable;
+
+    private static string ValidationMessage(string code)
+        => code switch
+        {
+            "AUTHORIZATION_NOT_FOUND" => "The referenced authorization receipt was not found or is not valid.",
+            "AUTHORIZATION_CONTEXT_MISMATCH" => "The completion does not match the authorized operation and identity.",
+            "SIGNATURE_INVALID" => "The stored receipt signature is invalid.",
+            _ => "The producer receipt request is invalid."
+        };
+
+    private static string ConflictMessage(string code)
+        => code == "IDEMPOTENCY_KEY_REUSED"
+            ? "The idempotency key is already bound to a different request."
+            : "The producer receipt request conflicts with durable state.";
+
+    private static string RetrievalMessage(string? code)
+        => code switch
+        {
+            "RECEIPT_NOT_FOUND" => "The producer receipt was not found.",
+            "TENANT_MISMATCH" => "The receipt is not bound to the authenticated tenant.",
+            "ACTOR_MISMATCH" => "The receipt is not bound to the authenticated actor.",
+            "AUDIENCE_MISMATCH" => "The receipt is not bound to the authenticated audience.",
+            "SIGNATURE_INVALID" => "The stored receipt signature is invalid.",
+            _ => "The durable producer receipt store is unavailable."
+        };
+}

