+namespace Keon.Runtime.Execution;
+
+/// <summary>
+/// Durable, SQLite-backed governed-action ledger (GMF-P2A): the durable
+/// <see cref="IControlledExecutionLedger"/> implementation that cuts launch mode over from
+/// <see cref="InMemoryControlledExecutionLedger"/> behind the receipt-persistence
+/// configuration switch (AC(b)(2)). Rows live in the append-only <c>GovernedActions</c> table
+/// (v2 schema, <see cref="ReceiptPersistenceSchema"/>) and carry an explicit durable-state
+/// origin (<c>durable-store-v2</c>); pre-cutover in-memory records are non-authoritative and
+/// are never imported — the schema cannot even name an imported origin.
+///
+/// Durability posture: WAL, busy timeout, foreign keys enforced, per-process-safe appends.
+/// The effect path stays disabled: this ledger performs no external I/O — its only effect is
+/// the runtime's own persistence boundary (same contract as
+/// <see cref="ControlledExecutionHandler"/>).
+///
+/// Schema initialization is owned by <see cref="ReceiptPersistenceSchema"/> and honors
+/// ReceiptPersistenceConfig.AutoMigrate in composition; this class never creates schema.
+/// </summary>
