+{
+    private readonly string _connectionString;
+
+    public SqliteControlledExecutionLedger(string connectionString)
+    {
+        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
+    }
+
+    /// <summary>
+    /// Opens a ledger connection and fails closed on a torn v2 schema before any state is
+    /// read or written (same consumption posture as SqliteAuthorityAccountingStore).
+    /// </summary>
+    private SQLiteConnection OpenChecked()
+    {
+        var connection = ReceiptPersistenceSchema.OpenConnection(_connectionString);
+        try
+        {
+            ReceiptPersistenceSchema.ValidateV2OrThrow(connection);
+            return connection;
+        }
+        catch
+        {
+            connection.Dispose();
+            throw;
+        }
+    }
+
+    /// <inheritdoc />
+    /// <remarks>
+    /// Append-only: a duplicate <see cref="GovernedActionRecord.ExecutionId"/> is rejected by
+    /// the primary key (one governed action per execution). Persistence failure commits
+    /// nothing (P1-C124 posture).
+    /// </remarks>
+    public Task AppendAsync(GovernedActionRecord record, CancellationToken ct = default)
+    {
+        ArgumentNullException.ThrowIfNull(record);
+
+        using var connection = OpenChecked();
+        using var command = connection.CreateCommand();
+        command.CommandText = @"
+INSERT INTO GovernedActions (
+    ExecutionId, DecisionReceiptId, CorrelationId, TenantId, ActorId, Capability, PolicyHash,
+    ActionContentHash, RecordedAtUtc, StateOrigin)
+VALUES (
+    @execution_id, @decision_receipt_id, @correlation_id, @tenant_id, @actor_id, @capability, @policy_hash,
+    @action_content_hash, @recorded_at_utc, @state_origin);";
+        command.Parameters.AddWithValue("@execution_id", record.ExecutionId.Value);
+        command.Parameters.AddWithValue("@decision_receipt_id", record.DecisionReceiptId);
+        command.Parameters.AddWithValue("@correlation_id", record.CorrelationId.Value);
+        command.Parameters.AddWithValue("@tenant_id", record.TenantId.Value);
+        command.Parameters.AddWithValue("@actor_id", record.ActorId.Value);
+        command.Parameters.AddWithValue("@capability", record.Capability);
+        command.Parameters.AddWithValue("@policy_hash", (object?)record.PolicyHash ?? DBNull.Value);
+        command.Parameters.AddWithValue("@action_content_hash", record.ActionContentHash);
+        command.Parameters.AddWithValue("@recorded_at_utc", record.RecordedAtUtc.UtcDateTime.ToString("O"));
