+    public Task<GovernedActionRecord?> GetByExecutionIdAsync(ExecutionId executionId, CancellationToken ct = default)
+    {
+        using var connection = OpenChecked();
+        using var command = connection.CreateCommand();
+        command.CommandText = "SELECT * FROM GovernedActions WHERE ExecutionId = @execution_id;";
+        command.Parameters.AddWithValue("@execution_id", executionId.Value);
+        using var reader = command.ExecuteReader();
+        return Task.FromResult(reader.Read() ? Read(reader) : null);
+    }
+
+    /// <inheritdoc />
+    public Task<IReadOnlyList<GovernedActionRecord>> GetByCorrelationIdAsync(CorrelationId correlationId, CancellationToken ct = default)
+    {
+        using var connection = OpenChecked();
+        using var command = connection.CreateCommand();
+        command.CommandText = "SELECT * FROM GovernedActions WHERE CorrelationId = @correlation_id ORDER BY RecordedAtUtc, ExecutionId;";
+        command.Parameters.AddWithValue("@correlation_id", correlationId.Value);
+        return Task.FromResult(Query(command));
+    }
