+        using var connection = OpenChecked();
+        using var command = connection.CreateCommand();
+        command.CommandText = "SELECT * FROM GovernedActions WHERE DecisionReceiptId = @decision_receipt_id ORDER BY RecordedAtUtc, ExecutionId;";
+        command.Parameters.AddWithValue("@decision_receipt_id", decisionReceiptId);
+        return Task.FromResult(Query(command));
+    }
+
+    private static IReadOnlyList<GovernedActionRecord> Query(SQLiteCommand command)
+    {
+        using var reader = command.ExecuteReader();
+        var results = new List<GovernedActionRecord>();
