+            CorrelationId: CorrelationId.From(Convert.ToString(reader["CorrelationId"])!),
+            TenantId: new TenantId(Convert.ToString(reader["TenantId"])!),
+            ActorId: new ActorId(Convert.ToString(reader["ActorId"])!),
+            Capability: Convert.ToString(reader["Capability"])!,
