+
+    /// <summary>
+    /// Idempotent, versioned initialization of the authority/accounting store schema
+    /// (the SQLite ledger line v1 -&gt; v2 migration). Safe to call from multiple processes:
+    /// the migration runs inside a single <c>BEGIN IMMEDIATE</c> transaction and only ever
+    /// adds objects (v1 rows are never rewritten or dropped).
+    /// </summary>
+    public static void InitializeAuthorityAccountingDatabase(string connectionString)
+    {
+        using var connection = OpenConnection(connectionString);
+        InitializeAuthorityAccountingCore(connection);
+    }
+
+    /// <summary>
+    /// Fails closed when the open connection's schema is not a complete v2 state
+    /// (AC(b)(1) at consumption time, not only at init): a torn or tampered schema can never
+    /// silently accept a write. Throws <see cref="InvalidOperationException"/> naming the
+    /// missing objects. Every store consumption path calls this before touching state.
+    /// </summary>
+    public static void ValidateV2OrThrow(SQLiteConnection connection)
+    {
+        var missing = FindMissingV2Objects(connection);
+        if (missing.Count > 0)
+        {
+            throw new InvalidOperationException(
+                "Authority/accounting schema is partially migrated and cannot present as v2: missing " +
+                string.Join(", ", missing) +
+                ". Store consumption fails closed on a torn schema state.");
+        }
+    }
+
+    /// <summary>
+    /// Opens a store connection with the durability posture the schema requires:
+    /// WAL (persistent, set at schema init), per-connection busy timeout, and foreign keys
+    /// enforced (<c>PRAGMA foreign_keys=1</c>, per-connection in SQLite).
+    /// </summary>
+    public static SQLiteConnection OpenConnection(string connectionString)
+    {
+        var connection = new SQLiteConnection(connectionString);
+        connection.Open();
+
+        using var pragma = connection.CreateCommand();
+        pragma.CommandText = $"PRAGMA busy_timeout={BusyTimeoutMs}; PRAGMA foreign_keys=1;";
+        pragma.ExecuteNonQuery();
+
+        return connection;
+    }
+
+    /// <summary>
+    /// Validates that a database presenting <c>user_version &gt;= 2</c> actually contains every
+    /// v2 object AND every v2 column. Returns the names of the missing entries
+    /// (empty = fully present). Table/column checks are what make a stub- or
+    /// wrong-shape-created table unable to present as v2.
+    /// </summary>
+    public static IReadOnlyList<string> FindMissingV2Objects(SQLiteConnection connection)
+    {
+        var missing = new List<string>();
+        foreach (var name in RequiredV2Objects)
+        {
+            using var command = connection.CreateCommand();
+            command.CommandText = "SELECT COUNT(*) FROM sqlite_master WHERE name = @name;";
+            command.Parameters.AddWithValue("@name", name);
+            if (Convert.ToInt32(command.ExecuteScalar()) == 0)
+            {
+                missing.Add(name);
+            }
+        }
+
+        foreach (var (table, columns) in RequiredV2Columns)
+        {
+            var present = new HashSet<string>(StringComparer.Ordinal);
+            using var command = connection.CreateCommand();
+            command.CommandText = $"PRAGMA table_info({table});";
+            using var reader = command.ExecuteReader();
+            while (reader.Read())
+            {
+                present.Add(Convert.ToString(reader["name"]) ?? string.Empty);
+            }
+
+            foreach (var column in columns)
+            {
+                if (!present.Contains(column))
+                {
+                    missing.Add(table + "." + column);
+                }
+            }
+        }
+
+        return missing;
+    }
+
+    private static readonly string[] RequiredV2Objects =
+    {
+        // v1 (preserved)
+        "PermissionSpendLedger",
+        "idx_permission_spend_permission",
+        // v2 authority/accounting state families (AC(a), P1-C096)
+        "EffectAttempts",
+        "BudgetReservations",
+        "ConcurrencySlots",
+        "PreEffectReceipts",
+        "PendingEffects",
+        "DenialReceipts",
+        "TerminalReceipts",
+        "Settlements",
+        // durable governed-action ledger (launch-ledger cutover target)
+        "GovernedActions",
+        // append-only / closed-set enforcement (AC(f))
+        "trg_permission_spend_ledger_immutable",
+        "trg_permission_spend_ledger_immutable_delete",
+        "trg_effect_attempts_immutable",
+        "trg_effect_attempts_immutable_delete",
+        "trg_budget_reservations_immutable_delete",
+        "trg_budget_reservations_quarantine_only",
+        "trg_concurrency_slots_immutable",
+        "trg_concurrency_slots_immutable_delete",
+        "trg_pre_effect_receipts_immutable",
+        "trg_pre_effect_receipts_immutable_delete",
+        "trg_pending_effects_immutable",
+        "trg_pending_effects_immutable_delete",
+        "trg_denial_receipts_immutable",
+        "trg_denial_receipts_immutable_delete",
+        "trg_terminal_receipts_immutable",
+        "trg_terminal_receipts_immutable_delete",
+        "trg_terminal_receipts_class_set",
+        "trg_settlements_immutable",
+        "trg_settlements_immutable_delete",
+        "trg_governed_actions_immutable",
+        "trg_governed_actions_immutable_delete"
+    };
+
+    // Column-level completeness per v2 table (name-only validation could not see a
+    // stub-shaped table). Fresh-initialization tests cross-check this map against the DDL:
+    // drift between the two fails FindMissingV2Objects on a real fresh database.
+    private static readonly IReadOnlyList<(string Table, string[] Columns)> RequiredV2Columns = new (string, string[])[]
+    {
+        ("PermissionSpendLedger", new[] { "PermissionId", "SpendIndex", "SpentAtUtc", "CreatedAtUtc" }),
+        ("EffectAttempts", new[]
+        {
+            "EffectId", "EffectClass", "DescriptorHash", "AttemptOrdinal", "TaskScopeKey", "PermissionId",
+            "SpendIndex", "Nonce", "Audience", "ExpiresAtUtc", "PolicyVersion", "LineageKey",
+            "SourceIdentityHash", "EnvironmentIdentityHash", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("BudgetReservations", new[]
+        {
+            "ReservationId", "EffectId", "BudgetScopeKey", "AmountMinor", "Currency", "CostState",
+            "CostPendingCode", "Status", "QuarantinedAtUtc", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("ConcurrencySlots", new[]
+        {
+            "SlotId", "SlotScope", "SlotIndex", "EffectId", "AcquiredAtUtc", "LeaseExpiresAtUtc", "StateOrigin"
+        }),
+        ("PreEffectReceipts", new[]
+        {
+            "EffectId", "DescriptorHash", "PermissionId", "AttemptOrdinal", "ReservationId", "SlotId",
+            "Audience", "ExpiresAtUtc", "PendingEffectMarker", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("PendingEffects", new[] { "EffectId", "PendingEffectMarker", "StartedAtUtc", "StateOrigin" }),
+        ("DenialReceipts", new[]
+        {
+            "DenialReceiptId", "EffectId", "PermissionId", "DenialCode", "WinnerEffectId",
+            "LinkedReceiptId", "ZeroExcessEffect", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("TerminalReceipts", new[]
+        {
+            "EffectId", "TerminalState", "SettledAmountMinor", "Currency", "CostPendingMarker",
+            "EvidenceManifestHash", "DenialReceiptId", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("Settlements", new[]
+        {
+            "SettlementId", "EffectId", "ReservationId", "PriorSettlementId", "Kind", "SettledAmountMinor",
+            "Currency", "CostPendingMarker", "EvidenceManifestHash", "StateOrigin", "CreatedAtUtc"
+        }),
+        ("GovernedActions", new[]
+        {
+            "ExecutionId", "DecisionReceiptId", "CorrelationId", "TenantId", "ActorId", "Capability",
+            "PolicyHash", "ActionContentHash", "RecordedAtUtc", "StateOrigin"
+        })
+    };
+
+    private static void InitializeAuthorityAccountingCore(SQLiteConnection connection)
+    {
+        using (var pragma = connection.CreateCommand())
+        {
+            // WAL is a persistent database property; busy_timeout/foreign_keys are
+            // per-connection (also set on every store connection via OpenConnection).
+            pragma.CommandText = $"PRAGMA journal_mode=WAL; PRAGMA busy_timeout={BusyTimeoutMs}; PRAGMA foreign_keys=1;";
+            pragma.ExecuteNonQuery();
+        }
+
+        var version = ReadUserVersion(connection);
+
+        if (version >= AuthorityAccountingSchemaVersion)
+        {
+            // A database that claims v2 must actually be v2: fail closed rather than let a
+            // torn or tampered state present as complete (AC(b)(1)).
+            var missing = FindMissingV2Objects(connection);
+            if (missing.Count > 0)
+            {
+                throw new InvalidOperationException(
+                    "Authority/accounting schema is partially migrated and cannot present as v2: missing " +
+                    string.Join(", ", missing) +
+                    ". Refusing to run against a torn schema state (PRAGMA user_version = " + version + ").");
+            }
+
+            return;
+        }
+
+        // v1 -> v2 migration (or fresh initialization straight to v2): one transaction, purely
+        // additive. V1 rows are never rewritten or dropped (P1-C108/P1-C112/P1-C116).
+        using var begin = connection.CreateCommand();
+        begin.CommandText = "BEGIN IMMEDIATE;";
+        begin.ExecuteNonQuery();
+
+        try
+        {
+            using (var ddl = connection.CreateCommand())
+            {
+                ddl.CommandText = GetAuthorityAccountingSchemaScript();
+                ddl.ExecuteNonQuery();
+            }
+
+            using (var versionWrite = connection.CreateCommand())
+            {
+                versionWrite.CommandText = $"PRAGMA user_version = {AuthorityAccountingSchemaVersion};";
+                versionWrite.ExecuteNonQuery();
+            }
+
+            using var commit = connection.CreateCommand();
+            commit.CommandText = "COMMIT;";
+            commit.ExecuteNonQuery();
+        }
+        catch
+        {
+            try
+            {
+                using var rollback = connection.CreateCommand();
+                rollback.CommandText = "ROLLBACK;";
+                rollback.ExecuteNonQuery();
+            }
+            catch (SQLiteException)
+            {
+                // The transaction may already have been rolled back by SQLite itself.
+            }
+
+            throw;
+        }
+
+        var post = FindMissingV2Objects(connection);
+        if (post.Count > 0)
+        {
+            throw new InvalidOperationException(
+                "Authority/accounting schema migration did not reach a complete v2 state: missing " +
+                string.Join(", ", post) + ".");
+        }
+    }
+
+    private static int ReadUserVersion(SQLiteConnection connection)
+    {
+        using var command = connection.CreateCommand();
+        command.CommandText = "PRAGMA user_version;";
+        return Convert.ToInt32(command.ExecuteScalar());
+    }
+
+    private static string SqlStringList(IEnumerable<string> values)
+        => string.Join(", ", values.Select(v => "'" + v.Replace("'", "''") + "'"));
+
+    /// <summary>
+    /// The authority/accounting store schema (spend-ledger line v2). Every table carries its
+    /// frozen-clause binding in its header comment. All DDL is <c>IF NOT EXISTS</c> so a crash
+    /// mid-migration is completed idempotently on the next initialization. Public so the
+    /// migration tests can reconstruct exact torn states.
+    /// </summary>
+    public static string GetAuthorityAccountingSchemaScript()
+    {
+        var codes = SqlStringList(Vocabulary.DenialFailurePendingCodes);
+        var classes = SqlStringList(Vocabulary.EffectClasses);
+        var inference = SqlStringList(Vocabulary.InferenceTerminals);
+        var execution = SqlStringList(Vocabulary.ExecutionTerminals);
+        var promotion = SqlStringList(Vocabulary.PromotionTerminals);
+        var allTerminals = SqlStringList(
+            Vocabulary.InferenceTerminals
+                .Concat(Vocabulary.ExecutionTerminals)
+                .Concat(Vocabulary.PromotionTerminals)
+                .Distinct(StringComparer.Ordinal));
+
+        return $@"
+-- ===========================================================================
+-- GMF-P2A authority/accounting store (SQLite ledger line v2, P1-C093/DR-006(a)).
+-- Durable state families (D6/A1-D6, P1-C096): spends/permission consumption
+-- (P1-C108), unique effect-attempt records (P1-C009/P1-C010/P1-C111),
+-- budget reservations incl. explicit unknown/pending cost (P1-C073/P1-C115),
+-- concurrency-slot state (P1-C109), pre-effect receipts (P1-C109 field list),
+-- pending-effect state (P1-C109), terminal receipts (P1-C110 field list,
+-- closed sets P1-C103-P1-C105), durable denial receipts (P1-C106),
+-- leaked-reservation quarantine state (P1-C113), append-only settlements
+-- (P1-C116). Validation-binding fields D6 names (descriptor hash, audience,
+-- nonce, expiry, policy version, lineage) are representable on the attempt
+-- row so P2B can run D6's full validation inside one transaction without an
+-- ALTER. This schema records authority/accounting state and confers nothing
+-- (D2, P1-C047/P1-C051).
+--
+-- The v1 shape is preserved verbatim below (IF NOT EXISTS: populated v1
+-- databases keep every row byte-for-byte; fresh databases are created at v2).
+-- ===========================================================================
+
+CREATE TABLE IF NOT EXISTS PermissionSpendLedger (
+    PermissionId TEXT NOT NULL,
+    SpendIndex INTEGER NOT NULL,
+    SpentAtUtc TEXT NOT NULL,
+    CreatedAtUtc TEXT NOT NULL,
+    PRIMARY KEY (PermissionId, SpendIndex)
+);
+
+CREATE INDEX IF NOT EXISTS idx_permission_spend_permission
+    ON PermissionSpendLedger(PermissionId);
+
+-- Unique effect-attempt records (P1-C009/P1-C010/P1-C111/P1-C017).
+-- UNIQUE (PermissionId, SpendIndex) denies cross-class spend reuse by
+-- construction (P1-C002); UNIQUE (TaskScopeKey, AttemptOrdinal) structurally
+-- denies attempt-ordinal reuse (P1-C009/P1-C010).
+CREATE TABLE IF NOT EXISTS EffectAttempts (
+    EffectId TEXT NOT NULL PRIMARY KEY,
+    EffectClass TEXT NOT NULL CHECK (EffectClass IN ({classes})),
+    DescriptorHash TEXT NOT NULL,
+    AttemptOrdinal INTEGER NOT NULL,
+    TaskScopeKey TEXT NOT NULL,
+    PermissionId TEXT NOT NULL,
+    SpendIndex INTEGER NOT NULL,
+    Nonce TEXT NOT NULL,
+    Audience TEXT NOT NULL,
+    ExpiresAtUtc TEXT NOT NULL,
+    PolicyVersion TEXT NOT NULL,
+    LineageKey TEXT NOT NULL,
+    SourceIdentityHash TEXT NOT NULL,
+    EnvironmentIdentityHash TEXT NOT NULL,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL,
+    UNIQUE (TaskScopeKey, AttemptOrdinal),
+    UNIQUE (PermissionId, SpendIndex),
+    FOREIGN KEY (PermissionId, SpendIndex) REFERENCES PermissionSpendLedger (PermissionId, SpendIndex)
+);
+
+-- Budget reservations (P1-C073/P1-C115): unknown cost stays reserved with the
+-- explicit pending marker FLEET_PENDING_UNKNOWN_COST and permits append-only
+-- settlement only. Status admits exactly one transition: the P1-C113 leak
+-- quarantine (active -> quarantined), enforced by trigger below.
+CREATE TABLE IF NOT EXISTS BudgetReservations (
+    ReservationId TEXT NOT NULL PRIMARY KEY,
+    EffectId TEXT NOT NULL,
+    BudgetScopeKey TEXT NOT NULL,
+    AmountMinor INTEGER,
+    Currency TEXT,
+    CostState TEXT NOT NULL CHECK (CostState IN ('known', 'unknown')),
+    CostPendingCode TEXT CHECK (CostPendingCode IN ('{Vocabulary.PendingUnknownCostCode}')),
+    Status TEXT NOT NULL DEFAULT 'active' CHECK (Status IN ('active', 'quarantined')),
+    QuarantinedAtUtc TEXT,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL,
+    CHECK ((CostState = 'known' AND AmountMinor IS NOT NULL AND Currency IS NOT NULL AND CostPendingCode IS NULL)
+        OR (CostState = 'unknown' AND AmountMinor IS NULL AND Currency IS NULL AND CostPendingCode IS NOT NULL)),
+    CHECK ((Status = 'active' AND QuarantinedAtUtc IS NULL)
+        OR (Status = 'quarantined' AND QuarantinedAtUtc IS NOT NULL)),
+    FOREIGN KEY (EffectId) REFERENCES EffectAttempts (EffectId)
+);
+
+-- Concurrency-slot state (P1-C109/P1-C120): a row is a held slot claim; the
+-- UNIQUE (SlotScope, SlotIndex) claim makes double acquisition structurally
+-- impossible. LeaseExpiresAtUtc is the lease-recovery input consumed by GMF-P2C.
+CREATE TABLE IF NOT EXISTS ConcurrencySlots (
+    SlotId TEXT NOT NULL PRIMARY KEY,
+    SlotScope TEXT NOT NULL,
+    SlotIndex INTEGER NOT NULL,
+    EffectId TEXT NOT NULL,
+    AcquiredAtUtc TEXT NOT NULL,
+    LeaseExpiresAtUtc TEXT,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    UNIQUE (SlotScope, SlotIndex),
+    FOREIGN KEY (EffectId) REFERENCES EffectAttempts (EffectId)
+);
+
+-- Pre-effect receipts, exact P1-C109 field list: effect identifier, descriptor
+-- hash, permission identifier, attempt ordinal, reservation reference, slot
+-- reference (where applicable), audience/expiry snapshot, pending-effect marker.
+-- Persisted atomically with spend (P1-C107); one receipt binds exactly one
+-- effect attempt (P1-C111).
+CREATE TABLE IF NOT EXISTS PreEffectReceipts (
+    EffectId TEXT NOT NULL PRIMARY KEY,
+    DescriptorHash TEXT NOT NULL,
+    PermissionId TEXT NOT NULL,
+    AttemptOrdinal INTEGER NOT NULL,
+    ReservationId TEXT NOT NULL,
+    SlotId TEXT,
+    Audience TEXT NOT NULL,
+    ExpiresAtUtc TEXT NOT NULL,
+    PendingEffectMarker TEXT NOT NULL CHECK (PendingEffectMarker = '{Vocabulary.PendingEffectMarker}'),
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL,
+    FOREIGN KEY (EffectId) REFERENCES EffectAttempts (EffectId),
+    FOREIGN KEY (ReservationId) REFERENCES BudgetReservations (ReservationId),
+    FOREIGN KEY (SlotId) REFERENCES ConcurrencySlots (SlotId)
+);
+
+-- Pending-effect state (P1-C102/P1-C109): the durable pending-effect marker;
+-- resolution is the terminal row (exactly one per effect, P1-C112).
+CREATE TABLE IF NOT EXISTS PendingEffects (
+    EffectId TEXT NOT NULL PRIMARY KEY,
+    PendingEffectMarker TEXT NOT NULL CHECK (PendingEffectMarker = '{Vocabulary.PendingEffectMarker}'),
+    StartedAtUtc TEXT NOT NULL,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    FOREIGN KEY (EffectId) REFERENCES EffectAttempts (EffectId)
+);
+
+-- Durable denial receipts (P1-C106). DenialReceiptId is generated per event by
+-- the store (never derived from effect/code): repeat conflict/race/quarantine
+-- denials each persist their own evidence row and return false.
+-- EffectId is lineage only and deliberately has NO foreign key: pre-spend
+-- denials precede any attempt row, and every derived denial-evidence path must
+-- work with a missing attempt row (trigger/evidence hardening).
+CREATE TABLE IF NOT EXISTS DenialReceipts (
+    DenialReceiptId TEXT NOT NULL PRIMARY KEY,
+    EffectId TEXT,
+    PermissionId TEXT,
+    DenialCode TEXT NOT NULL CHECK (DenialCode IN ({codes})),
+    WinnerEffectId TEXT,
+    LinkedReceiptId TEXT,
+    ZeroExcessEffect INTEGER NOT NULL CHECK (ZeroExcessEffect = 1),
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL
+);
+
+-- Terminal receipts, exact P1-C110 field list: effect identifier, terminal
+-- state (one of P1-C103-P1-C105), cost state (settled amount or explicit
+-- unknown/pending marker, P1-C115), evidence-manifest hash (P1-C080/P1-C081),
+-- lineage (denial/attempt/settlement links: attempt via EffectId, denial via
+-- DenialReceiptId, settlements via Settlements.EffectId).
+-- PRIMARY KEY (EffectId) makes at most one terminal per effect structural
+-- (P1-C102/P1-C112).
+CREATE TABLE IF NOT EXISTS TerminalReceipts (
+    EffectId TEXT NOT NULL PRIMARY KEY,
+    TerminalState TEXT NOT NULL CHECK (TerminalState IN ({allTerminals})),
+    SettledAmountMinor INTEGER,
+    Currency TEXT,
+    CostPendingMarker TEXT CHECK (CostPendingMarker IN ('{Vocabulary.PendingUnknownCostCode}')),
+    EvidenceManifestHash TEXT NOT NULL,
+    DenialReceiptId TEXT,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL,
+    CHECK ((SettledAmountMinor IS NOT NULL AND Currency IS NOT NULL AND CostPendingMarker IS NULL)
+        OR (SettledAmountMinor IS NULL AND Currency IS NULL AND CostPendingMarker IS NOT NULL)),
+    FOREIGN KEY (EffectId) REFERENCES EffectAttempts (EffectId),
+    FOREIGN KEY (DenialReceiptId) REFERENCES DenialReceipts (DenialReceiptId)
+);
+
+-- Append-only settlement records (P1-C115/P1-C116): settlement/adjustment/
+-- refund/human-resolution appends new evidence and never rewrites the terminal
+-- or a prior settlement; PriorSettlementId chains the append lineage.
+CREATE TABLE IF NOT EXISTS Settlements (
+    SettlementId TEXT NOT NULL PRIMARY KEY,
+    EffectId TEXT NOT NULL,
+    ReservationId TEXT,
+    PriorSettlementId TEXT,
+    Kind TEXT NOT NULL CHECK (Kind IN ('settlement', 'adjustment', 'refund', 'human-resolution')),
+    SettledAmountMinor INTEGER,
+    Currency TEXT,
+    CostPendingMarker TEXT CHECK (CostPendingMarker IN ('{Vocabulary.PendingUnknownCostCode}')),
+    EvidenceManifestHash TEXT,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}'),
+    CreatedAtUtc TEXT NOT NULL,
+    CHECK ((SettledAmountMinor IS NOT NULL AND Currency IS NOT NULL AND CostPendingMarker IS NULL)
+        OR (SettledAmountMinor IS NULL AND Currency IS NULL AND CostPendingMarker IS NOT NULL)),
+    FOREIGN KEY (EffectId) REFERENCES TerminalReceipts (EffectId),
+    FOREIGN KEY (ReservationId) REFERENCES BudgetReservations (ReservationId),
+    FOREIGN KEY (PriorSettlementId) REFERENCES Settlements (SettlementId)
+);
+
+-- Durable governed-action ledger (in-memory launch ledger -> durable cutover,
+-- AC(b)(2)): the ControlledExecutionHandler's one internal effect, append-only.
+CREATE TABLE IF NOT EXISTS GovernedActions (
+    ExecutionId TEXT NOT NULL PRIMARY KEY,
+    DecisionReceiptId TEXT NOT NULL,
+    CorrelationId TEXT NOT NULL,
+    TenantId TEXT NOT NULL,
+    ActorId TEXT NOT NULL,
+    Capability TEXT NOT NULL,
+    PolicyHash TEXT,
+    ActionContentHash TEXT NOT NULL,
+    RecordedAtUtc TEXT NOT NULL,
+    StateOrigin TEXT NOT NULL CHECK (StateOrigin = '{Vocabulary.DurableStateOrigin}')
+);
+
+CREATE INDEX IF NOT EXISTS idx_governed_actions_correlation
+    ON GovernedActions(CorrelationId);
+CREATE INDEX IF NOT EXISTS idx_governed_actions_decision
+    ON GovernedActions(DecisionReceiptId);
+
+-- ---------------------------------------------------------------------------
+-- Append-only enforcement (AC(f), P1-C112/P1-C116): UPDATE/DELETE on history
+-- rows is rejected. V1 spend rows are covered too (P1-C108: never deleted or
+-- decremented).
+-- ---------------------------------------------------------------------------
+CREATE TRIGGER IF NOT EXISTS trg_permission_spend_ledger_immutable BEFORE UPDATE ON PermissionSpendLedger
+BEGIN SELECT RAISE(ABORT, 'append-only: PermissionSpendLedger rows are never updated (P1-C108)'); END;
+CREATE TRIGGER IF NOT EXISTS trg_permission_spend_ledger_immutable_delete BEFORE DELETE ON PermissionSpendLedger
+BEGIN SELECT RAISE(ABORT, 'append-only: PermissionSpendLedger rows are never deleted (P1-C108)'); END;
+
+CREATE TRIGGER IF NOT EXISTS trg_effect_attempts_immutable BEFORE UPDATE ON EffectAttempts
+BEGIN SELECT RAISE(ABORT, 'append-only: EffectAttempts rows are never updated (P1-C111)'); END;
+CREATE TRIGGER IF NOT EXISTS trg_effect_attempts_immutable_delete BEFORE DELETE ON EffectAttempts
+BEGIN SELECT RAISE(ABORT, 'append-only: EffectAttempts rows are never deleted (P1-C111)'); END;
+
+-- BudgetReservations: never deleted; the ONLY permitted update is the P1-C113
+-- leak quarantine (active -> quarantined) with every other column unchanged.
+CREATE TRIGGER IF NOT EXISTS trg_budget_reservations_immutable_delete BEFORE DELETE ON BudgetReservations
+BEGIN SELECT RAISE(ABORT, 'append-only: BudgetReservations rows are never deleted (P1-C113)'); END;
+CREATE TRIGGER IF NOT EXISTS trg_budget_reservations_quarantine_only BEFORE UPDATE ON BudgetReservations
+WHEN NOT (OLD.Status = 'active' AND NEW.Status = 'quarantined'
+    AND OLD.ReservationId IS NEW.ReservationId
+    AND OLD.EffectId IS NEW.EffectId
+    AND OLD.BudgetScopeKey IS NEW.BudgetScopeKey
+    AND OLD.AmountMinor IS NEW.AmountMinor
+    AND OLD.Currency IS NEW.Currency
+    AND OLD.CostState IS NEW.CostState
+    AND OLD.CostPendingCode IS NEW.CostPendingCode
+    AND OLD.StateOrigin IS NEW.StateOrigin
+    AND OLD.CreatedAtUtc IS NEW.CreatedAtUtc
+    AND NEW.QuarantinedAtUtc IS NOT NULL)
+BEGIN SELECT RAISE(ABORT, 'append-only: BudgetReservations admits only the active->quarantined transition (P1-C113)'); END;
+
+CREATE TRIGGER IF NOT EXISTS trg_concurrency_slots_immutable BEFORE UPDATE ON ConcurrencySlots
+BEGIN SELECT RAISE(ABORT, 'append-only: ConcurrencySlots rows are never updated (P1-C120)'); END;
+CREATE TRIGGER IF NOT EXISTS trg_concurrency_slots_immutable_delete BEFORE DELETE ON ConcurrencySlots
+BEGIN SELECT RAISE(ABORT, 'append-only: ConcurrencySlots rows are never deleted (P1-C120)'); END;
+
+CREATE TRIGGER IF NOT EXISTS trg_pre_effect_receipts_immutable BEFORE UPDATE ON PreEffectReceipts
