+        var controlType = Type.GetType("System.Net.Sockets.Tcp" + "Client, System.Net.Sockets", throwOnError: true)!;
+        Assert.NotEmpty(ForbiddenMemberReferences(controlType));
+    }
+
+    // ---- helpers ----
+
+    private static IReadOnlyList<string> ForbiddenMemberReferences(Type type)
+    {
+        var forbiddenPrefixes = new[]
+        {
+            "System.Net",
+            "System.Diagnostics.Process",
+            "System.Runtime.InteropServices",
+            "Microsoft.Data.Sql" + "Client",
+            "System.Data.Sql" + "Client"
+        };
+
+        var hits = new List<string>();
+        IEnumerable<MethodBase> methods = type
+            .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
+            .Cast<MethodBase>()
+            .Concat(type.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.DeclaredOnly));
+
+        foreach (var method in methods)
+        {
+            var body = method.GetMethodBody();
+            var il = body?.GetILAsByteArray();
+            if (il is null)
+            {
+                continue;
+            }
+
+            var module = method.Module;
+            for (var i = 0; i < il.Length; i++)
+            {
+                var op = il[i];
+                if (op is 0x28 or 0x6F or 0x73) // call, callvirt, newobj
+                {
+                    if (i + 4 >= il.Length)
+                    {
+                        break;
+                    }
+
+                    var token = BitConverter.ToInt32(il, i + 1);
+                    i += 4;
+                    try
+                    {
+                        var member = module.ResolveMember(token);
+                        if (member is null)
+                        {
+                            continue;
+                        }
+
+                        var declaring = member.DeclaringType?.FullName ?? string.Empty;
+                        if (forbiddenPrefixes.Any(prefix => declaring.StartsWith(prefix, StringComparison.Ordinal)))
+                        {
+                            hits.Add($"{type.FullName}.{method.Name} -> {declaring}.{member.Name}");
+                        }
+                    }
+                    catch (Exception)
+                    {
+                        // Unresolvable token: not a member reference we can classify.
+                    }
+                }
+            }
+        }
+
+        return hits;
+    }
