+            SlotId: slotId,
+            SlotScope: slotScope,
+            SlotIndex: slotIndex,
+            LeaseExpiresAtUtc: lease,
+            AttemptedAtUtc: Now);
+    }
+
+    public static AtomicSpendRequest CreateAtomicRequest(
+        Permission? permission,
+        PermissionSpendRequest? spend = null,
+        BeginEffectRequest? begin = null,
+        CanonicalConstraintProjection? constraints = null,
+        string? presentedAudience = null,
+        string? presentedNonce = null,
+        DelegationChain? chain = null,
+        BudgetAdmission? budget = null,
+        string? runtimeProfileHash = null,
+        string? descriptorBoundProfileHash = null,
+        PermissionEnvelopePresentation? envelope = null,
+        Action<SpendBoundaryStep>? stepObserver = null)
+    {
+        var effectivePermission = permission ?? CreatePermission();
+        var effectiveSpend = spend ?? CreateSpendRequest(effectivePermission);
+        var effectiveBegin = begin ?? CreateBegin(
+            permissionId: effectivePermission.PermissionId,
+            effectClass: effectivePermission.EffectClass,
+            descriptorHash: effectiveSpend.EffectDescriptorHash,
+            audience: constraints?.Audience ?? "actuator-aud",
+            nonce: constraints?.Nonce ?? "nonce-default");
+        return new AtomicSpendRequest
+        {
+            Permission = permission,
+            DelegationChain = chain,
+            Spend = effectiveSpend,
+            Constraints = constraints ?? new CanonicalConstraintProjection(
+                effectiveBegin.Audience, effectiveBegin.Nonce),
+            PresentedAudience = presentedAudience ?? effectiveBegin.Audience,
+            PresentedNonce = presentedNonce ?? effectiveBegin.Nonce,
+            RuntimeProfileHash = runtimeProfileHash,
+            DescriptorBoundProfileHash = descriptorBoundProfileHash,
+            Envelope = envelope,
+            Begin = effectiveBegin,
+            Budget = budget,
+            StepObserver = stepObserver,
+        };
+    }
+
+    public static (DelegationChain Chain, Permission Permission) CreateDelegationLineage(
+        DevKeyProvider keys,
+        string effectClass = "fleet.model.infer",
+        string? chainId = null,
+        string notBefore = "2026-01-01T00:00:00Z",
+        string notAfter = "2026-12-31T23:59:59Z")
+    {
+        using var key = Key.Create(SignatureAlgorithm.Ed25519,
+            new KeyCreationParameters { ExportPolicy = KeyExportPolicies.AllowPlaintextExport });
+        var kid = "delegate-" + Guid.NewGuid().ToString("N");
+        keys.Register(kid, key);
+
+        var binding = new DelegationTargetBinding { Type = "receipt_id", Value = "synthetic-1234" };
+        var payload = new
+        {
+            delegate_id = kid,
+            not_after = notAfter,
+            not_before = notBefore,
+            principal_id = "principal-1",
+            scope = effectClass,
+            target_binding = binding,
+            tenant_id = "tenant-1",
+        };
+        var sig = SignatureAlgorithm.Ed25519.Sign(key, KeonCanonicalJsonV1.Canonicalize(payload));
+
+        var chain = new DelegationChain
+        {
+            ChainId = chainId ?? "chain-" + Guid.NewGuid().ToString("N"),
+            Links = new[]
+            {
+                new DelegationLink
+                {
+                    TenantId = "tenant-1",
+                    PrincipalId = "principal-1",
+                    DelegateId = kid,
+                    Scope = effectClass,
+                    NotBefore = notBefore,
+                    NotAfter = notAfter,
+                    TargetBinding = binding,
+                    Signature = Convert.ToBase64String(sig),
+                },
+            },
+        };
+
+        var perm = CreatePermission(
+            PermissionGrantKind.Delegation,
+            subjectId: kid,
+            effectClass: effectClass,
+            delegationChainId: chain.ChainId);
+
+        return (chain, perm);
+    }
