+            }
+
+            case "audience":
+            {
+                var permission = AtomicSpendFixtures.CreatePermission(permissionId: permissionId);
+                var spend = AtomicSpendFixtures.CreateSpendRequest(permission);
+                request = AtomicSpendFixtures.CreateAtomicRequest(permission, spend,
+                    AtomicSpendFixtures.CreateBegin(effectId: effectId, permissionId: permissionId, descriptorHash: spend.EffectDescriptorHash),
+                    constraints: new CanonicalConstraintProjection("aud-bound", "nonce-" + effectId),
+                    presentedAudience: "aud-elsewhere");
+                expectedCode = AtomicSpendDenialMap.Audience;
+                break;
+            }
+
+            case "nonce":
+            {
+                var permission = AtomicSpendFixtures.CreatePermission(permissionId: permissionId);
+                var spend = AtomicSpendFixtures.CreateSpendRequest(permission);
+                request = AtomicSpendFixtures.CreateAtomicRequest(permission, spend,
