+    // ---- Equivalence-provable verdict pass (verification_class) ----
+
+    [Fact]
+    public void VerdictPass_AgreesWithPermissionSpendVerifier_OnSharedFixtures()
+    {
+        foreach (var fixture in SharedEquivalenceFixtures())
+        {
+            var ledger = new PermissionSpendLedger();
+            foreach (var pre in fixture.PreConsumed)
+            {
+                ledger.TryRecordSpend(pre, maxUses: 1, AtomicSpendFixtures.Now, out _);
+            }
+
+            var verifier = new PermissionSpendVerifier(
+                new DelegationChainVerifier(_registry, _keys),
+                _registry,
+                ledger,
+                _keys);
+
+            var verifierResult = verifier.VerifyAndSpend(
+                fixture.Permission, fixture.Spend, AtomicSpendFixtures.Now, fixture.Chain);
+            var boundaryResult = _transaction.EvaluateVerdicts(
+                fixture.Request,
+                new StubBoundaryRead
+                {
+                    Spends = fixture.PreConsumed.Count,
+                    SpenderEffectId = fixture.PreConsumed.Count > 0 ? "fx-original" : null,
+                });
+
+            AssertVerdictAgrees(verifierResult, boundaryResult, fixture.Name);
+        }
+    }
+
+    /// <summary>
+    /// THE equivalence comparison (shared by the suite and its mutation control):
+    /// satisfied-vs-denied and verdict family must agree.
+    /// </summary>
+    private static void AssertVerdictAgrees(
+        PermissionSpendResult verifier, VerdictEvaluation boundary, string fixtureName)
+    {
+        Assert.True(verifier.IsSatisfied == boundary.IsSatisfied,
+            $"[{fixtureName}] divergence: verifier satisfied={verifier.IsSatisfied}, boundary satisfied={boundary.IsSatisfied}");
+        if (!verifier.IsSatisfied)
+        {
+            Assert.True(verifier.Verdict == boundary.PermissionSpendFamily,
+                $"[{fixtureName}] divergence: verifier family={verifier.Verdict}, boundary family={boundary.PermissionSpendFamily}");
+        }
+    }
+
+    [Fact]
+    public void VerdictPass_MutationControl_WeakenedVerdict_IsFlaggedByTheSuite()
+    {
+        // R7 mutation control — the REAL comparison, no fabricated results:
+        // the weakening is injected through the production verdict path (the
+        // same fixture with its fault neutralized runs through the real pass and
+        // produces exactly what a weakened production verdict would produce),
+        // and the suite's comparator must flag the divergence — RED. The
+        // unweakened pair must pass — GREEN. If the comparator were broken to
+        // always agree, the RED assertion below would fail.
+        var faulted = SharedEquivalenceFixtures().First(f => f.Name == "expired");
+        var neutralized = SharedEquivalenceFixtures().First(f => f.Name == "satisfied-policy");
+
+        var verifierResult = new PermissionSpendVerifier(
+            new DelegationChainVerifier(_registry, _keys), _registry, new PermissionSpendLedger(), _keys)
+            .VerifyAndSpend(faulted.Permission, faulted.Spend, AtomicSpendFixtures.Now, faulted.Chain);
+        Assert.False(verifierResult.IsSatisfied);
+
+        // Production verdict path on the neutralized fixture: the real pass
+        // (a weakened expiry verdict behaves exactly like this result).
+        var weakenedByPath = _transaction.EvaluateVerdicts(neutralized.Request, new StubBoundaryRead());
+        Assert.True(weakenedByPath.IsSatisfied);
+
+        // RED: the suite's comparator must reject the divergent pair.
+        Assert.ThrowsAny<Xunit.Sdk.XunitException>(() =>
+            AssertVerdictAgrees(verifierResult, weakenedByPath, "mutation-expired-weakened"));
+
+        // GREEN: the same comparator passes the real, unweakened pair.
+        var realBoundary = _transaction.EvaluateVerdicts(faulted.Request, new StubBoundaryRead());
+        AssertVerdictAgrees(verifierResult, realBoundary, "expired");
+    }
+
+    private sealed record EquivalenceFixture(
+        string Name,
+        IPermission? Permission,
+        PermissionSpendRequest Spend,
+        DelegationChain? Chain,
+        AtomicSpendRequest Request,
+        IReadOnlyList<string> PreConsumed);
+
+    private IEnumerable<EquivalenceFixture> SharedEquivalenceFixtures()
+    {
+        // Single-fault fixtures across the verifier's check family, plus
+        // multi-fault fixtures that pin the frozen check ORDER: each multi-fault
+        // fixture's expected verdict is the earlier check in the verifier's
