+    [Fact]
+    public void ForgedOrWidenedReissue_OfRecordedEffectId_DeniesEnvelopeForgery_NeverIdempotent()
+    {
+        // R1 security control + mutation proof: the verdict pass runs BEFORE the
+        // idempotent short-circuit and presentation equality covers the full
+        // canonical presentation. With the ordering weakened (idempotent return
+        // before validation) or equality narrowed, this control goes RED — the
+        // old shape returned IsSatisfied/IdempotentReplay for these forgeries.
+        var permission = AtomicSpendFixtures.CreatePermission(permissionId: "perm-r1");
+        var spend = AtomicSpendFixtures.CreateSpendRequest(permission);
+        var begin = AtomicSpendFixtures.CreateBegin(
+            effectId: "fx-r1", permissionId: "perm-r1",
+            descriptorHash: spend.EffectDescriptorHash,
+            nonce: "nonce-r1", audience: "actuator-aud",
+            amountMinor: 100, currency: "USD",
+            slotId: "slot-r1", slotScope: "scope-r1", slotIndex: 1);
+        var constraints = new CanonicalConstraintProjection("actuator-aud", "nonce-r1");
+
+        Assert.True(_transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission, spend, begin, constraints)).IsSatisfied);
+
+        // Widened re-presentation of the recorded effect id (budget amount).
+        var widened = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission, spend, begin with { AmountMinor = 999 }, constraints));
+        Assert.False(widened.IsSatisfied);
+        Assert.Equal(AtomicSpendDenialMap.EnvelopeForgery, widened.DenialCode);
+        Assert.Equal(AtomicSpendVerdict.EnvelopeForgery, widened.Verdict);
+
+        // Widened re-presentation of the recorded effect id (slot).
+        var widenedSlot = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission, spend, begin with { SlotIndex = 7 }, constraints));
+        Assert.False(widenedSlot.IsSatisfied);
+        Assert.Equal(AtomicSpendDenialMap.EnvelopeForgery, widenedSlot.DenialCode);
+
+        // Forged/widened envelope over the recorded effect id.
+        var forged = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission, spend, begin, constraints,
+            envelope: new PermissionEnvelopePresentation(
+                permission.PermissionId, begin.EffectId, permission.EffectDescriptorHash,
+                permission.ConstraintsHash, constraints.Audience, constraints.Nonce,
+                "2027-12-31T23:59:59Z", 9, null, null)));
+        Assert.False(forged.IsSatisfied);
+        Assert.Equal(AtomicSpendDenialMap.EnvelopeForgery, forged.DenialCode);
+
+        // The true idempotent re-presentation still returns the recorded bundle.
+        var idempotent = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission, spend, begin, constraints));
+        Assert.True(idempotent.IsSatisfied);
+        Assert.True(idempotent.IdempotentReplay);
+
+        // Zero excess effect from the forgeries (raw SQL).
+        Assert.Equal(1, _db.Count("EffectAttempts"));
+        Assert.Equal(1, _db.Count("PermissionSpendLedger", "PermissionId = 'perm-r1'"));
+        Assert.Equal(1, _db.Count("BudgetReservations"));
+    }
