+{
+    private readonly TempAuthorityDb _db = new();
+    private readonly SqliteAuthorityAccountingStore _store;
+    private readonly Keon.Verify.DelegationRevocationRegistry _registry = new();
+    private readonly Keon.Verify.DevKeyProvider _keys = new();
