+    private Keon.Verify.AtomicSpendResult Execute(
+        Keon.Contracts.Authority.Permission permission,
+        BeginEffectRequest begin,
+        Action<SpendBoundaryStep>? stepObserver = null)
+    {
+        var spend = AtomicSpendFixtures.CreateSpendRequest(permission);
+        return _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission,
+            spend with { EffectDescriptorHash = begin.DescriptorHash },
+            begin,
+            stepObserver: stepObserver));
+    }
+
+    /// <summary>Simulates the crash-reopen: all pooled handles dropped, fresh raw connection.</summary>
+    private int ReopenedCount(string table, string where = "1=1")
+    {
