+    [Fact]
+    public void GMF_NEG_006_DescriptorSubstitution_Denies_BothHashesRetained_ComparatorAgrees()
+    {
+        // R8: the expected hashes are derived from LITERAL canonical bytes
+        // (hand-written RFC 8785 JCS form) through an implementation-free
+        // SHA-256 — never x == f(y) where x := f(y). The production
+        // canonicalizer's output is then cross-checked against those literal
+        // expectations (two independent derivations of the same values).
+        var boundLiteral = System.Text.Encoding.UTF8.GetBytes(
+            """{"amount_limit":100,"effect_class":"fleet.model.infer","resource":"synthetic-resource"}""");
+        var substitutedLiteral = System.Text.Encoding.UTF8.GetBytes(
+            """{"amount_limit":100,"effect_class":"fleet.model.infer","resource":"synthetic-resource-SUBSTITUTED"}""");
+        static string IndependentSha256(byte[] bytes)
+            => $"sha256:{Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(bytes))}";
+
+        var boundHash = IndependentSha256(boundLiteral);             // literal-derived expectation
+        var substitutedHash = IndependentSha256(substitutedLiteral); // literal-derived expectation
+
+        // Cross-derivation: the production canonicalizer's bytes for both
+        // descriptors must hash to the literal-derived expectations.
+        Assert.Equal(boundHash, IndependentSha256(AtomicSpendFixtures.CanonicalDescriptor()));
+        Assert.Equal(substitutedHash, IndependentSha256(Keon.Canonicalization.KeonCanonicalJsonV1.Canonicalize(new
+        {
+            effect_class = "fleet.model.infer",
+            resource = "synthetic-resource-SUBSTITUTED",
+            amount_limit = 100,
+        })));
+
+        // Permission binds hash H; the presented effective descriptor is the
+        // substituted one.
+        var permission = AtomicSpendFixtures.CreatePermission(
+            permissionId: "perm-neg-006", effectDescriptorHash: boundHash);
+        var substitutedBytes = Keon.Canonicalization.KeonCanonicalJsonV1.Canonicalize(new
+        {
+            effect_class = "fleet.model.infer",
+            resource = "synthetic-resource-SUBSTITUTED",
+            amount_limit = 100,
+        });
+
+        var spend = AtomicSpendFixtures.CreateSpendRequest(permission,
+            effectDescriptorHash: substitutedHash, canonicalDescriptor: substitutedBytes);
+        var begin = AtomicSpendFixtures.CreateBegin(
+            effectId: "fx-neg-006", permissionId: "perm-neg-006", descriptorHash: substitutedHash);
+
+        var denied = Execute(permission, spend, begin);
+
+        Assert.False(denied.IsSatisfied);
+        Assert.Equal("FLEET_DENIED_DESCRIPTOR_MISMATCH", denied.DenialCode);
+
+        // Independent canonical-bytes comparator (P1-C070): the hash recomputed
+        // from the presented canonical bytes equals the literal-derived
+        // substituted expectation and differs from the permission's bound hash.
+        var recomputedFromPresented = IndependentSha256(substitutedBytes);
+        Assert.Equal(substitutedHash, recomputedFromPresented);
+        Assert.NotEqual(boundHash, recomputedFromPresented);
+
+        // Cleanup: retain denial + both hashes (both remain observable evidence;
+        // the forgery never rewrites the canonical grant's bound hash).
+        Assert.Equal(1, _db.Count("DenialReceipts", "DenialCode = 'FLEET_DENIED_DESCRIPTOR_MISMATCH'"));
