+/// <summary>
+/// Temp-file SQLite fixture for authority/accounting store tests (synthetic/public data
+/// only, A1-D22). Deleted on dispose including -wal/-shm files; cleanup never runs before
+/// assertions, so it can never hide a failed assertion.
+/// </summary>
+internal sealed class TempAuthorityDb : IDisposable
+{
+    public string DbPath { get; }
+    public string ConnectionString { get; }
+
+    public TempAuthorityDb()
+    {
+        DbPath = Path.Combine(Path.GetTempPath(), $"keon_authority_store_{Guid.NewGuid():n}.db");
+        ConnectionString = $"Data Source={DbPath};Version=3;";
+    }
+
+    /// <summary>
+    /// Opens a raw observer connection (DB-level observer: raw SQL, never the store API
+    /// under test). Foreign-key enforcement is off by default on raw connections, which the
+    /// trigger-hardening tests rely on.
+    /// </summary>
+    public SQLiteConnection OpenRaw()
+    {
+        var connection = new SQLiteConnection(ConnectionString);
+        connection.Open();
+        return connection;
+    }
+
+    public void Exec(string sql, SQLiteConnection? connection = null)
+    {
+        if (connection is not null)
+        {
+            using var command = connection.CreateCommand();
+            command.CommandText = sql;
+            command.ExecuteNonQuery();
+            return;
+        }
+
+        using var fresh = OpenRaw();
+        using var freshCommand = fresh.CreateCommand();
+        freshCommand.CommandText = sql;
+        freshCommand.ExecuteNonQuery();
+    }
+
+    public object? Scalar(string sql, SQLiteConnection? connection = null)
+    {
+        SQLiteConnection owned = connection ?? OpenRaw();
+        try
+        {
+            using var command = owned.CreateCommand();
+            command.CommandText = sql;
+            return command.ExecuteScalar();
+        }
+        finally
+        {
+            if (connection is null)
+            {
+                owned.Dispose();
+            }
+        }
+    }
+
+    public int Count(string table, string where = "1=1")
+        => Convert.ToInt32(Scalar($"SELECT COUNT(*) FROM {table} WHERE {where};"));
+
+    public void Dispose()
+    {
+        SQLiteConnection.ClearAllPools();
+        foreach (var path in new[] { DbPath, DbPath + "-wal", DbPath + "-shm" })
+        {
+            if (File.Exists(path))
+                File.Delete(path);
+        }
+    }
