+    [Fact]
+    public async Task ConcurrentWriters_SeparateConnections_AdmitExactlyValidSet_RaceLosersRecorded_ZeroOverspend()
+    {
+        // AC(c): concurrent writers on separate connections; exactly the valid set is
+        // admitted, losers record FLEET_DENIED_RACE_LOST (P1-C074/P1-C120) with winner
+        // linkage, and there is zero overspend.
+        const int maxUses = 3;
+        const int racers = 12;
+
+        // Separate store instances => separate connections per writer.
+        var storeA = new SqliteAuthorityAccountingStore(_db.ConnectionString);
+        var storeB = new SqliteAuthorityAccountingStore(_db.ConnectionString);
+
+        var wins = 0;
+        var losses = 0;
+        await Task.WhenAll(Enumerable.Range(0, racers).Select(i => Task.Run(() =>
+        {
+            var request = NewRequest(
+                $"fx-race-{i}",
+                permission: "perm-race",
+                maxUses: maxUses,
+                task: $"task-race-{i}");
+            if ((i % 2 == 0 ? storeA : storeB).TryBeginEffect(request, out _))
+            {
+                Interlocked.Increment(ref wins);
+            }
+            else
+            {
+                Interlocked.Increment(ref losses);
+            }
+        })));
+
+        Assert.Equal(maxUses, wins);
+        Assert.Equal(racers - maxUses, losses);
+
+        // Zero overspend: exactly maxUses consumption rows (raw SQL observer).
+        Assert.Equal(maxUses, _db.Count("PermissionSpendLedger", "PermissionId = 'perm-race'"));
+        Assert.Equal(maxUses, _db.Count("EffectAttempts", "PermissionId = 'perm-race'"));
+
+        // Every loser recorded FLEET_DENIED_RACE_LOST with winner linkage and zero excess
+        // effect (literal pin, A-F3) — read back with raw SQL (DB-level observer) as well as
+        // through the store API.
+        Assert.Equal(racers - maxUses, _db.Count("DenialReceipts"));
+        Assert.Equal(racers - maxUses, _db.Count("DenialReceipts", "DenialCode = 'FLEET_DENIED_RACE_LOST'"));
+        Assert.Equal(racers - maxUses, _db.Count("DenialReceipts", "WinnerEffectId IS NOT NULL AND ZeroExcessEffect = 1"));
+        var denials = _store.GetDenialReceipts(null);
+        Assert.Equal(racers - maxUses, denials.Count);
+        Assert.All(denials, d =>
+        {
+            Assert.Equal("FLEET_DENIED_RACE_LOST", d.DenialCode);
+            Assert.NotNull(d.WinnerEffectId);
+            Assert.Equal(1, d.ZeroExcessEffect);
+        });
+
+        // Losers left zero excess effect: no attempt rows beyond the maxUses winners.
+        Assert.Equal(maxUses, _db.Count("EffectAttempts"));
+    }
