+/// <summary>Structural description of one path to a spend-ledger append.</summary>
+internal sealed record SpendPathDescriptor(
+    string Surface,
+    bool IsStorePrimitive,
+    bool RequiresCanonicalPermission,
+    bool AcceptsEnvelope,
+    bool ReachesAppendThroughCanonicalValidation = false);
+
+/// <summary>
+/// Machine-checkable P1-C048 checker: enumerates spend-ledger append paths from
+/// the compiled surface (IL call graph) and returns the violations of the
+/// checked property. An empty result means the property holds over the
+/// enumerated surface.
+/// </summary>
+internal static class EnvelopeNonAuthorityChecker
+{
+    /// <summary>
+    /// The checked property (P1-C048): no envelope-only path reaches the spend
+    /// ledger without canonical IPermission validation.
+    /// </summary>
+    public static IReadOnlyList<string> Check(IReadOnlyList<SpendPathDescriptor> spendPaths)
+    {
+        var violations = new List<string>();
+        foreach (var path in spendPaths)
+        {
+            var validated = path.RequiresCanonicalPermission || path.ReachesAppendThroughCanonicalValidation;
+            if (path.AcceptsEnvelope && !validated)
+            {
+                violations.Add($"{path.Surface}: envelope-capable spend path without canonical IPermission validation (P1-C048).");
+            }
+            else if (!path.IsStorePrimitive && !validated)
+            {
+                violations.Add($"{path.Surface}: spend-ledger append path without canonical IPermission validation (P1-C048).");
+            }
+        }
+
+        return violations;
+    }
+
+    /// <summary>
+    /// Structural enumeration (R5): IL member-reference/call-graph analysis over
+    /// the compiled surface. Every method that can reach a spend-ledger append —
+    /// directly or through wrappers — is a spend path; name-based binding is not
+    /// used, so a wrapper cannot evade the enumeration.
+    /// </summary>
+    public static IReadOnlyList<SpendPathDescriptor> EnumerateSpendPaths(params Assembly[] assemblies)
+    {
+        // Keys are module-scoped ("module|token") — bare metadata tokens collide
+        // across assemblies.
+        var appendKeys = new HashSet<string>(StringComparer.Ordinal);
+        var validationKeys = new HashSet<string>(StringComparer.Ordinal);
+        var storePrimitiveTypes = new HashSet<Type>
+        {
+            typeof(SqlitePermissionSpendLedger),
+            typeof(SqliteAuthorityAccountingStore),
+            typeof(Keon.Verify.PermissionSpendLedger),
+            typeof(Keon.Contracts.Authority.IPermissionSpendLedger),
+        };
+
+        foreach (var method in AppendPrimitives())
+        {
+            appendKeys.Add(Key(method));
+        }
+
+        foreach (var method in CanonicalValidationNodes())
+        {
+            validationKeys.Add(Key(method));
+        }
+
+        // Collect every declared method across the surface and its IL call edges.
+        var methods = new List<MethodBase>();
+        foreach (var assembly in assemblies)
+        {
+            foreach (var type in assembly.GetTypes())
+            {
+                methods.AddRange(type
+                    .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
+                    .Cast<MethodBase>());
+                methods.AddRange(type.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.DeclaredOnly));
+            }
+        }
+
+        var edges = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
+        foreach (var method in methods)
+        {
+            edges[Key(method)] = CallEdges(method);
+        }
+
+        // Reachability to an append (transitive through wrappers).
+        var reachesAppend = new HashSet<string>(StringComparer.Ordinal);
+        var reachesValidation = new HashSet<string>(StringComparer.Ordinal);
+        bool changed = true;
+        while (changed)
+        {
+            changed = false;
+            foreach (var (methodKey, callees) in edges)
+            {
+                foreach (var callee in callees)
+                {
+                    if (appendKeys.Contains(callee) && reachesAppend.Add(methodKey))
+                    {
+                        changed = true;
+                    }
+
+                    if (validationKeys.Contains(callee) && reachesValidation.Add(methodKey))
+                    {
+                        changed = true;
+                    }
+
+                    if (reachesAppend.Contains(callee) && reachesAppend.Add(methodKey))
+                    {
+                        changed = true;
+                    }
+
+                    if (reachesValidation.Contains(callee) && reachesValidation.Add(methodKey))
+                    {
+                        changed = true;
+                    }
+                }
+            }
+        }
+
+        var paths = new List<SpendPathDescriptor>();
+        foreach (var method in methods)
+        {
+            var methodKey = Key(method);
+            if (!reachesAppend.Contains(methodKey) && !appendKeys.Contains(methodKey))
+            {
+                continue;
+            }
+
+            var parameterTypes = method.GetParameters().Select(p => p.ParameterType).ToArray();
+            paths.Add(new SpendPathDescriptor(
+                $"{method.DeclaringType?.FullName}.{method.Name}",
+                IsStorePrimitive: method.DeclaringType is not null && storePrimitiveTypes.Contains(method.DeclaringType),
+                RequiresCanonicalPermission: parameterTypes.Any(RequiresPermissionInRequest),
+                AcceptsEnvelope: parameterTypes.Any(t => t == typeof(Keon.Verify.PermissionEnvelopePresentation)),
+                ReachesAppendThroughCanonicalValidation: reachesValidation.Contains(methodKey)));
+        }
+
+        return paths;
+    }
+
+    private static string Key(MethodBase method) => $"{method.Module.FullyQualifiedName}|{method.MetadataToken}";
+
+    /// <summary>True when a parameter is, or carries, canonical IPermission evidence.</summary>
+    public static bool RequiresPermissionInRequest(Type requestType)
+        => requestType == typeof(Keon.Contracts.Authority.IPermission)
+           || requestType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
+               .Any(p => p.PropertyType == typeof(Keon.Contracts.Authority.IPermission));
+
+    private static IEnumerable<MethodInfo> AppendPrimitives()
+    {
+        yield return typeof(SqlitePermissionSpendLedger).GetMethod("TryRecordSpend")!;
+        foreach (var method in typeof(SqliteAuthorityAccountingStore).GetMethods()
+                     .Where(m => m.Name is "TryBeginEffect" or "RecordDenial"))
+        {
+            yield return method;
+        }
+
+        foreach (var method in typeof(Keon.Contracts.Authority.IPermissionSpendLedger).GetMethods())
+        {
+            yield return method;
+        }
+    }
+
+    private static IEnumerable<MethodInfo> CanonicalValidationNodes()
+    {
+        yield return typeof(Keon.Verify.PermissionSpendVerifier).GetMethod("VerifyAndSpend")!;
+        yield return typeof(Keon.Verify.AtomicEffectSpendTransaction).GetMethod("Execute")!;
+        yield return typeof(Keon.Verify.AtomicEffectSpendTransaction).GetMethod("EvaluateVerdicts")!;
+    }
+
+    /// <summary>IL call edges (call/callvirt/newobj member-reference keys) of one method.</summary>
+    private static HashSet<string> CallEdges(MethodBase method)
+    {
+        var edges = new HashSet<string>(StringComparer.Ordinal);
+        var il = method.GetMethodBody()?.GetILAsByteArray();
+        if (il is null)
+        {
+            return edges;
+        }
+
+        var module = method.Module;
+        for (var i = 0; i < il.Length; i++)
+        {
+            var op = il[i];
+            if (op is 0x28 or 0x6F or 0x73) // call, callvirt, newobj
+            {
+                if (i + 4 >= il.Length)
+                {
+                    break;
+                }
+
+                var token = BitConverter.ToInt32(il, i + 1);
+                i += 4;
+                try
+                {
+                    var member = module.ResolveMember(token);
+                    if (member is MethodBase callee)
+                    {
+                        edges.Add(Key(callee));
+                    }
+                }
+                catch (Exception)
+                {
+                    // Unresolvable token: not a classifiable member reference.
+                }
+            }
+        }
+
+        return edges;
+    }
+}
