+            ExpiresAtUtc: "2026-12-31T23:59:59Z",
+            RemainingUseProjection: 1,
+            ApprovalBinding: "approval-synthetic",
+            ProofMaterial: "proof-synthetic");
+
+        var cases = new (string Name, Keon.Verify.PermissionEnvelopePresentation? Envelope, Keon.Contracts.Authority.Permission? Perm)[]
+        {
+            ("forged-descriptor", faithful with { DescriptorHash = AtomicSpendFixtures.Sha256Hex(new byte[] { 5 }) }, permission),
+            ("widened-constraints", faithful with { ConstraintsHash = "sha256:" + new string('c', 64) }, permission),
+            ("widened-expiry", faithful with { ExpiresAtUtc = "2027-12-31T23:59:59Z" }, permission),
+            ("widened-remaining-use", faithful with { RemainingUseProjection = 9 }, permission),
+            ("reissued-permission-id", faithful with { PermissionId = "perm-reissued-by-someone-else" }, permission),
+            ("forged-nonce", faithful with { Nonce = "nonce-never-bound" }, permission),
+            ("forged-audience", faithful with { Audience = "aud-elsewhere" }, permission),
+            ("envelope-only", faithful, null),
+        };
+
+        foreach (var (name, envelope, perm) in cases)
+        {
+            var denied = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+                perm,
+                begin: AtomicSpendFixtures.CreateBegin(
+                    effectId: $"fx-proof-059-{name}", permissionId: "perm-proof-059",
+                    descriptorHash: spend.EffectDescriptorHash,
+                    audience: constraints.Audience, nonce: constraints.Nonce),
+                constraints: constraints,
+                envelope: envelope));
+
+            Assert.False(denied.IsSatisfied);
+            Assert.Equal("FLEET_DENIED_ENVELOPE_FORGERY", denied.DenialCode);
+            Assert.Equal(Keon.Verify.AtomicSpendVerdict.EnvelopeForgery, denied.Verdict);
+        }
+
+        // Canonical permission P unconsumed by the forgeries; zero effect; zero
+        // spend rows (raw SQL, independent of the API under test).
+        Assert.Equal(0, _db.Count("PermissionSpendLedger", "PermissionId = 'perm-proof-059'"));
+        Assert.Equal(0, _db.Count("EffectAttempts", "EffectId LIKE 'fx-proof-059%'"));
+        Assert.Equal(0, _db.Count("BudgetReservations"));
+        Assert.Equal(cases.Length, _db.Count("DenialReceipts", "DenialCode = 'FLEET_DENIED_ENVELOPE_FORGERY'"));
+
+        // The assertion binds: the faithful presentation admits exactly once.
+        var admitted = _transaction.Execute(AtomicSpendFixtures.CreateAtomicRequest(
+            permission,
+            begin: AtomicSpendFixtures.CreateBegin(
+                effectId: "fx-proof-059-faithful", permissionId: "perm-proof-059",
+                descriptorHash: spend.EffectDescriptorHash,
+                audience: constraints.Audience, nonce: constraints.Nonce),
+            constraints: constraints,
+            envelope: faithful));
+        Assert.True(admitted.IsSatisfied);
+        Assert.Equal(1, _db.Count("PermissionSpendLedger", "PermissionId = 'perm-proof-059'"));
+    }
