+using System.Text.Json;
+using Keon.Contracts.Identifiers;
+using Keon.Contracts.Spine;
+using Keon.Runtime.Spine;
+
+namespace Keon.Runtime.Tests;
+
+public sealed class InMemorySpineEventStoreTests
+{
+    [Fact]
+    public async Task AppendAsync_DuplicateEventId_Throws()
+    {
+        var store = new InMemorySpineEventStore();
+        var eventId = UuidV7.New();
+        var spineId = UuidV7.New();
+        var correlationId = UuidV7.New();
+
+        await store.AppendAsync(CreateEvent(eventId, spineId, correlationId, sequence: 1));
+
+        var duplicate = CreateEvent(eventId, spineId, correlationId, sequence: 2);
+
+        await Assert.ThrowsAsync<DuplicateSpineEventIdException>(() => store.AppendAsync(duplicate));
+    }
+
+    [Fact]
+    public async Task AppendAsync_MissingSequence_Throws()
+    {
+        var store = new InMemorySpineEventStore();
+        var spineId = UuidV7.New();
+        var correlationId = UuidV7.New();
+
+        var missingSequence = CreateEvent(UuidV7.New(), spineId, correlationId, sequence: null);
+
+        await Assert.ThrowsAsync<SpineSequenceMissingException>(() => store.AppendAsync(missingSequence));
+    }
+
+    [Fact]
+    public async Task AppendAsync_EqualSequence_Throws()
+    {
+        var store = new InMemorySpineEventStore();
+        var spineId = UuidV7.New();
+        var correlationId = UuidV7.New();
+
+        await store.AppendAsync(CreateEvent(UuidV7.New(), spineId, correlationId, sequence: 1));
+        var equalSequence = CreateEvent(UuidV7.New(), spineId, correlationId, sequence: 1);
+
+        await Assert.ThrowsAsync<SpineSequenceRegressionException>(() => store.AppendAsync(equalSequence));
+    }
+
+    [Fact]
+    public async Task ReplayAsync_ReturnsOrderedDefensiveCopy()
+    {
+        var store = new InMemorySpineEventStore();
+        var spineId = UuidV7.New();
+        var correlationId = UuidV7.New();
+
+        var first = CreateEvent(UuidV7.New(), spineId, correlationId, sequence: 1);
+        var second = CreateEvent(UuidV7.New(), spineId, correlationId, sequence: 2);
+
+        await store.AppendAsync(first);
+        await store.AppendAsync(second);
+
+        var replay1 = await store.ReplayAsync(first.TenantId, first.SpineId, first.ActorId);
+        Assert.Collection(
+            replay1,
+            e => Assert.Equal(1, e.Sequence),
+            e => Assert.Equal(2, e.Sequence));
+
+        var mutableReplay = Assert.IsType<List<SpineEvent>>(replay1);
+        mutableReplay.Clear();
+
+        var replay2 = await store.ReplayAsync(first.TenantId, first.SpineId, first.ActorId);
+        Assert.Equal(2, replay2.Count);
+        Assert.Equal(1, replay2[0].Sequence);
+        Assert.Equal(2, replay2[1].Sequence);
+    }
+
+    private static SpineEvent CreateEvent(Guid eventId, Guid spineId, Guid correlationId, long? sequence)
+    {
+        var payload = JsonSerializer.SerializeToElement(new { kind = "test" });
+
+        return new SpineEvent(
+            eventId: eventId,
+            spineId: spineId,
+            tenantId: "tenant:test",
+            actorId: "actor:test",
+            correlationId: correlationId,
+            causationId: null,
+            interactionId: null,
+            occurredAt: DateTimeOffset.UtcNow,
+            ingestedAt: null,
+            sequence: sequence,
+            eventType: "keon.runtime.test",
+            payload: payload);
+    }
+}

