+using System.Data.SQLite;
+using Keon.Contracts;
+using Keon.Contracts.Identifiers;
+using Keon.Runtime.Execution;
+using Keon.Runtime.Observability.Persistence;
+
+namespace Keon.Runtime.Tests;
+
+/// <summary>
+/// GMF-P2A durable governed-action ledger (AC(b)(2), AC(b)(3)): the SqliteControlledExecutionLedger
+/// round-trips governed actions across close/reopen (restart durability), binds them to the
+/// execution/correlation/decision-receipt keys, records an explicit durable-state origin, and
+/// is strictly append-only.
+/// </summary>
+public sealed class SqliteControlledExecutionLedgerTests : IDisposable
+{
+    private static readonly DateTimeOffset Now = DateTimeOffset.Parse("2026-07-01T12:00:00Z");
+
+    private readonly TempAuthorityDb _db = new();
+    private readonly SqliteControlledExecutionLedger _ledger;
+
+    public SqliteControlledExecutionLedgerTests()
+    {
+        ReceiptPersistenceSchema.InitializeAuthorityAccountingDatabase(_db.ConnectionString);
+        _ledger = new SqliteControlledExecutionLedger(_db.ConnectionString);
+    }
+
+    public void Dispose() => _db.Dispose();
+
+    [Fact]
+    public async Task Append_ThenGetByExecutionId_RoundTripsGovernedAction()
+    {
+        var record = NewRecord("exec-1", "dec-1", "corr-1");
+        await _ledger.AppendAsync(record);
+
+        var read = await _ledger.GetByExecutionIdAsync(new ExecutionId("exec-1"));
+        Assert.NotNull(read);
+        Assert.Equal("exec-1", read!.ExecutionId.Value);
+        Assert.Equal("dec-1", read.DecisionReceiptId);
+        Assert.Equal("corr-1", read.CorrelationId.Value);
+        Assert.Equal("tenant-1", read.TenantId.Value);
+        Assert.Equal("actor-1", read.ActorId.Value);
+        Assert.Equal("runtime.execute", read.Capability);
+        Assert.Equal("sha256:policy-1", read.PolicyHash);
+        Assert.Equal("sha256:action-1", read.ActionContentHash);
+        Assert.Equal(Now, read.RecordedAtUtc);
+    }
+
+    [Fact]
+    public async Task GetByCorrelationId_And_GetByDecisionReceiptId_ReturnBoundRecords()
+    {
+        await _ledger.AppendAsync(NewRecord("exec-2", "dec-2", "corr-2"));
+        await _ledger.AppendAsync(NewRecord("exec-3", "dec-3", "corr-2"));
+        await _ledger.AppendAsync(NewRecord("exec-4", "dec-2", "corr-3"));
+
+        var byCorrelation = await _ledger.GetByCorrelationIdAsync(CorrelationId.From("corr-2"));
+        Assert.Equal(2, byCorrelation.Count);
+
+        var byDecision = await _ledger.GetByDecisionReceiptIdAsync("dec-2");
+        Assert.Equal(2, byDecision.Count);
+    }
+
+    [Fact]
+    public async Task RecordsSurviveCloseReopen_RestartDurability()
+    {
+        await _ledger.AppendAsync(NewRecord("exec-restart", "dec-restart", "corr-restart"));
+
+        // Close/reopen of the database (process-restart analogue).
+        SQLiteConnection.ClearAllPools();
+        var reopened = new SqliteControlledExecutionLedger(_db.ConnectionString);
+
+        var read = await reopened.GetByExecutionIdAsync(new ExecutionId("exec-restart"));
+        Assert.NotNull(read);
+        Assert.Equal("sha256:action-1", read!.ActionContentHash);
+    }
+
+    [Fact]
+    public async Task DurableRows_CarryExplicitDurableStateOrigin_AndImportedOriginIsRejected()
+    {
+        await _ledger.AppendAsync(NewRecord("exec-origin", "dec-origin", "corr-origin"));
+
+        // DB-level observer: the durable-state origin is explicit on the row (AC(b)(2)).
+        Assert.Equal("durable-store-v2", _db.Scalar(
+            "SELECT StateOrigin FROM GovernedActions WHERE ExecutionId = 'exec-origin';"));
+
+        // A pre-cutover in-memory record cannot even be imported: an imported origin is
+        // structurally rejected by the schema.
+        Assert.Throws<SQLiteException>(() => _db.Exec(@"
+INSERT INTO GovernedActions (
+    ExecutionId, DecisionReceiptId, CorrelationId, TenantId, ActorId, Capability, PolicyHash,
+    ActionContentHash, RecordedAtUtc, StateOrigin)
+VALUES ('exec-imported', 'd', 'c', 't', 'a', 'runtime.execute', NULL, 'h', 'now', 'in-memory-imported');"));
+    }
+
+    [Fact]
+    public async Task Append_IsStrictlyAppendOnly_DuplicateExecutionIdRejected()
+    {
+        await _ledger.AppendAsync(NewRecord("exec-dup", "dec-dup", "corr-dup"));
+
+        var ex = await Assert.ThrowsAsync<SQLiteException>(
+            () => _ledger.AppendAsync(NewRecord("exec-dup", "dec-dup", "corr-dup")));
+        Assert.Equal(SQLiteErrorCode.Constraint, ex.ResultCode);
+
+        // Raw observer: UPDATE/DELETE on governed-action history is rejected too.
+        Assert.Throws<SQLiteException>(() => _db.Exec("UPDATE GovernedActions SET Capability = 'tampered';"));
+        Assert.Throws<SQLiteException>(() => _db.Exec("DELETE FROM GovernedActions;"));
+        Assert.Equal(1, _db.Count("GovernedActions"));
+    }
+
+    private static GovernedActionRecord NewRecord(string executionId, string decisionReceiptId, string correlationId)
+        => new(
+            ExecutionId: new ExecutionId(executionId),
+            DecisionReceiptId: decisionReceiptId,
+            CorrelationId: CorrelationId.From(correlationId),
+            TenantId: new TenantId("tenant-1"),
+            ActorId: new ActorId("actor-1"),
+            Capability: "runtime.execute",
+            PolicyHash: "sha256:policy-1",
+            ActionContentHash: "sha256:action-1",
+            RecordedAtUtc: Now);
+}
