+    // ---- GMF-P2A: consumption permanence (P1-C108/D21) across cutover and restart ----
+
+    [Fact]
+    public void ConsumedSpend_IsNeverResurrected_AcrossRestartOrCutover()
+    {
+        var ledger = new SqlitePermissionSpendLedger(_connectionString);
+        Assert.True(ledger.TryRecordSpend("perm-permanent", maxUses: 1, Now, out _));
+
+        // Restart (fresh instances over the same file) + cutover back and forth between the
+        // in-memory and durable ledgers: consumption is never resurrected or re-spent.
+        SQLiteConnection.ClearAllPools();
+        var afterRestart = new SqlitePermissionSpendLedger(_connectionString);
+        Assert.Equal(1, afterRestart.GetSpendCount("perm-permanent"));
+        Assert.False(afterRestart.TryRecordSpend("perm-permanent", maxUses: 1, Now, out _));
+
+        // The v2 authority store sees the same permanent consumption (cutover path).
+        var store = new SqliteAuthorityAccountingStore(_connectionString);
+        Assert.False(store.TryBeginEffect(NewRequest("fx-perm", "perm-permanent"), out _));
+        using (var raw = OpenRaw())
+        using (var count = new SQLiteCommand("SELECT COUNT(*) FROM PermissionSpendLedger WHERE PermissionId = 'perm-permanent';", raw))
+        {
+            Assert.Equal(1, Convert.ToInt32(count.ExecuteScalar()));
+        }
+    }
+
+    [Fact]
+    public void TryRecordSpend_WorksOnMigratedV2Database_AlongsideAuthorityStore()
+    {
+        // v1 semantics are preserved on the v2 schema: sequential indexes, permanent counts.
+        var ledger = new SqlitePermissionSpendLedger(_connectionString);
+        Assert.True(ledger.TryRecordSpend("perm-coexist", maxUses: 2, Now, out var first));
+        Assert.True(ledger.TryRecordSpend("perm-coexist", maxUses: 2, Now, out var second));
+        Assert.Equal(1, first);
+        Assert.Equal(2, second);
+        Assert.False(ledger.TryRecordSpend("perm-coexist", maxUses: 2, Now, out _));
+
+        var store = new SqliteAuthorityAccountingStore(_connectionString);
+        Assert.True(store.TryBeginEffect(NewRequest("fx-coexist", "perm-other"), out _));
+        Assert.Equal(2, ledger.GetSpendCount("perm-coexist"));
+    }
+
+    private SQLiteConnection OpenRaw()
